from fractions import Fraction
from math import gcd, isqrt
from itertools import product

def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _ok_mat(m):
    if not isinstance(m, list) or len(m) == 0:
        return False
    w = -1
    for row in m:
        if not isinstance(row, list) or len(row) == 0:
            return False
        if w < 0:
            w = len(row)
        if len(row) != w:
            return False
        for v in row:
            if not _is_int(v):
                return False
    return True

def _fr(m):
    return [[Fraction(v) for v in row] for row in m]

def _tr(X):
    return [[X[i][j] for i in range(len(X))] for j in range(len(X[0]))]

def _mul(X, Y):
    return [[sum((X[i][k] * Y[k][j] for k in range(len(Y))), Fraction(0)) for j in range(len(Y[0]))] for i in range(len(X))]

def _sub(X, Y):
    return [[X[i][j] - Y[i][j] for j in range(len(X[0]))] for i in range(len(X))]

def _inv(A):
    n = len(A)
    M = [list(A[i]) + [Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    for c in range(n):
        p = None
        for r in range(c, n):
            if M[r][c] != 0:
                p = r
                break
        if p is None:
            return None
        M[c], M[p] = M[p], M[c]
        pv = M[c][c]
        M[c] = [v / pv for v in M[c]]
        for r in range(n):
            if r != c and M[r][c] != 0:
                f = M[r][c]
                M[r] = [M[r][j] - f * M[c][j] for j in range(2 * n)]
    return [row[n:] for row in M]

def _det(A):
    n = len(A)
    M = [list(r) for r in A]
    d = Fraction(1)
    for c in range(n):
        p = None
        for r in range(c, n):
            if M[r][c] != 0:
                p = r
                break
        if p is None:
            return Fraction(0)
        if p != c:
            M[c], M[p] = M[p], M[c]
            d = -d
        d = d * M[c][c]
        for r in range(c + 1, n):
            f = M[r][c] / M[c][c]
            M[r] = [M[r][j] - f * M[c][j] for j in range(n)]
    return d

def _inertia(S):
    M = [list(r) for r in S]
    n = len(M)
    pos = 0
    neg = 0
    act = list(range(n))
    while act:
        piv = None
        for i in act:
            if M[i][i] != 0:
                piv = i
                break
        if piv is None:
            pair = None
            for i in act:
                for j in act:
                    if i != j and M[i][j] != 0:
                        pair = (i, j)
                        break
                if pair is not None:
                    break
            if pair is None:
                break
            i, j = pair
            for k in range(n):
                M[i][k] = M[i][k] + M[j][k]
            for k in range(n):
                M[k][i] = M[k][i] + M[k][j]
            piv = i
        a = M[piv][piv]
        if a > 0:
            pos += 1
        else:
            neg += 1
        act = [k for k in act if k != piv]
        for r in act:
            f = M[r][piv] / a
            if f != 0:
                for k in range(n):
                    M[r][k] = M[r][k] - f * M[piv][k]
                for k in range(n):
                    M[k][r] = M[k][r] - f * M[k][piv]
    return (pos, neg, n - pos - neg)

def _block(A, B, D):
    top = [list(A[i]) + list(B[i]) for i in range(len(A))]
    Bt = _tr(B)
    bot = [list(Bt[i]) + list(D[i]) for i in range(len(D))]
    return top + bot

def _sym(X):
    return all(X[i][j] == X[j][i] for i in range(len(X)) for j in range(len(X)))

def _parts(case):
    A = case.get('A')
    B = case.get('B')
    D = case.get('D')
    if not (_ok_mat(A) and _ok_mat(B) and _ok_mat(D)):
        return None
    n = len(A)
    m = len(D)
    if len(A[0]) != n or len(D[0]) != m or len(B) != n or len(B[0]) != m:
        return None
    A = _fr(A)
    B = _fr(B)
    D = _fr(D)
    if not (_sym(A) and _sym(D)):
        return None
    return (A, B, D)

def _schur(A, B, D):
    Ai = _inv(A)
    if Ai is None:
        return (None, None)
    return (Ai, _sub(D, _mul(_tr(B), _mul(Ai, B))))

def _add3(u, v):
    return (u[0] + v[0], u[1] + v[1], u[2] + v[2])

def _sq_class_eq(x, y):
    if x == 0 or y == 0:
        return x == y
    r = x / y
    if r < 0:
        return False
    a = r.numerator
    b = r.denominator
    return isqrt(a) ** 2 == a and isqrt(b) ** 2 == b

def _schur_q(case):
    P = _parts(case)
    if P is None:
        return False
    A, B, D = P
    Ai, S = _schur(A, B, D)
    if S is None:
        return False
    n = len(A)
    m = len(D)
    M = _block(A, B, D)
    K = _mul(Ai, B)
    L = [[Fraction(1 if i == j else 0) for j in range(n)] + list(K[i]) for i in range(n)]
    L = L + [[Fraction(0)] * n + [Fraction(1 if i == j else 0) for j in range(m)] for i in range(m)]
    Z = [[Fraction(0)] * m for _ in range(n)]
    AS = _block(A, Z, S)
    ok_cong = _mul(_tr(L), _mul(AS, L)) == M
    ok_det = _det(M) == _det(A) * _det(S)
    ok_in = _inertia(M) == _add3(_inertia(A), _inertia(S))
    return ok_cong and ok_det and ok_in

def _schur_z(case):
    P = _parts(case)
    if P is None or not _schur_q(case):
        return False
    A, B, D = P
    Ai, S = _schur(A, B, D)
    K = _mul(Ai, B)
    return all(v.denominator == 1 for row in K for v in row) and all(v.denominator == 1 for row in S for v in row)

def _block_only(case):
    P = _parts(case)
    if P is None:
        return False
    A, B, D = P
    n = len(A)
    m = len(D)
    M = _block(A, B, D)
    Z = [[Fraction(0)] * m for _ in range(n)]
    AD = _block(A, Z, D)
    return _inertia(M) == _inertia(AD) and _sq_class_eq(_det(M), _det(AD))

def _inv_mod2(A):
    n = len(A)
    M = [[A[i][j] % 2 for j in range(n)] + [1 if i == j else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        p = None
        for r in range(c, n):
            if M[r][c] == 1:
                p = r
                break
        if p is None:
            return None
        M[c], M[p] = M[p], M[c]
        for r in range(n):
            if r != c and M[r][c] == 1:
                M[r] = [(M[r][j] + M[c][j]) % 2 for j in range(2 * n)]
    return [row[n:] for row in M]

def _mm2(X, Y):
    return [[sum(X[i][k] * Y[k][j] for k in range(len(Y))) % 2 for j in range(len(Y[0]))] for i in range(len(X))]

def _gf2_fold(case):
    P = _parts(case)
    if P is None:
        return False
    A, B, D = P
    if _det(A).numerator % 2 == 0:
        return False
    Ai, S = _schur(A, B, D)
    if S is None:
        return False
    if any(v.denominator % 2 == 0 for row in S for v in row):
        return False
    S2 = [[v.numerator % 2 for v in row] for row in S]
    Ai2 = _inv_mod2([[int(v) for v in row] for row in A])
    if Ai2 is None:
        return False
    Bi = [[int(v) % 2 for v in row] for row in B]
    Di = [[int(v) % 2 for v in row] for row in D]
    T = _mm2(_tr(Bi), _mm2(Ai2, Bi))
    G = [[(Di[i][j] + T[i][j]) % 2 for j in range(len(Di))] for i in range(len(Di))]
    if S2 != G:
        return False
    M = _block(A, B, D)
    if all(int(M[i][i]) % 2 == 0 for i in range(len(M))):
        return all(S[i][i].numerator % 2 == 0 for i in range(len(S)))
    return True

def _mirror_components(p, q):
    segs = []
    for x in range(2 * p):
        for y in range(2 * q + 1):
            if (x + y) % 2 == 1:
                for dy in (1, -1):
                    y2 = y + dy
                    if 0 <= y2 <= 2 * q:
                        segs.append(((x, y), (x + 1, y2)))
    idx = {s: i for i, s in enumerate(segs)}
    par = list(range(len(segs)))
    def find(i):
        while par[i] != i:
            par[i] = par[par[i]]
            i = par[i]
        return i
    def join(s, t):
        if s in idx and t in idx:
            a = find(idx[s])
            b = find(idx[t])
            if a != b:
                par[a] = b
    for x, y in product(range(2 * p + 1), range(2 * q + 1)):
        if (x + y) % 2 == 0:
            continue
        P = (x, y)
        on_x = x == 0 or x == 2 * p
        on_y = y == 0 or y == 2 * q
        if not on_x and not on_y:
            join(((x - 1, y - 1), P), (P, (x + 1, y + 1)))
            join(((x - 1, y + 1), P), (P, (x + 1, y - 1)))
        elif on_y:
            yi = 1 if y == 0 else 2 * q - 1
            join(((x - 1, yi), P), (P, (x + 1, yi)))
        else:
            xi = 1 if x == 0 else 2 * p - 1
            if xi < x:
                join(((xi, y - 1), P), ((xi, y + 1), P))
            else:
                join((P, (xi, y - 1)), (P, (xi, y + 1)))
    return len({find(i) for i in range(len(segs))})

def _mirror(case):
    p = case.get('p')
    q = case.get('q')
    k = case.get('components')
    if not (_is_int(p) and _is_int(q) and _is_int(k)):
        return False
    if p < 1 or q < 1 or p > 12 or q > 12:
        return False
    c = _mirror_components(p, q)
    return c == gcd(p, q) and c == k

def check_case(case):
    if not isinstance(case, dict):
        return False
    mode = case.get('mode')
    if mode == 'schur_q':
        return bool(_schur_q(case))
    if mode == 'schur_z':
        return bool(_schur_z(case))
    if mode == 'block_only':
        return bool(_block_only(case))
    if mode == 'gf2_fold':
        return bool(_gf2_fold(case))
    if mode == 'mirror_curve':
        return bool(_mirror(case))
    return False

from fractions import Fraction
from itertools import product


def _mm(X, Y):
    r = len(X)
    k = len(Y)
    c = len(Y[0])
    out = []
    for i in range(r):
        row = []
        for j in range(c):
            acc = 0
            for t in range(k):
                acc = acc + X[i][t] * Y[t][j]
            row.append(acc)
        out.append(row)
    return out


def _tr(X):
    return [list(col) for col in zip(*X)]


def _sub(X, Y):
    return [[X[i][j] - Y[i][j] for j in range(len(X[0]))] for i in range(len(X))]


def _det(X):
    n = len(X)
    A = [[Fraction(v) for v in row] for row in X]
    d = Fraction(1)
    for c in range(n):
        p = -1
        for r in range(c, n):
            if A[r][c] != 0:
                p = r
                break
        if p < 0:
            return Fraction(0)
        if p != c:
            A[c], A[p] = A[p], A[c]
            d = -d
        d = d * A[c][c]
        for r in range(c + 1, n):
            f = A[r][c] / A[c][c]
            if f != 0:
                for j in range(c, n):
                    A[r][j] = A[r][j] - f * A[c][j]
    return d


def _adj(X):
    n = len(X)
    cof = []
    for i in range(n):
        row = []
        for j in range(n):
            minor = [[X[a][b] for b in range(n) if b != j] for a in range(n) if a != i]
            v = _det(minor)
            if (i + j) % 2 == 1:
                v = -v
            row.append(v)
        cof.append(row)
    return _tr(cof)


def _inv(X):
    d = _det(X)
    if d == 0:
        return None
    adj = _adj(X)
    return [[Fraction(v) / d for v in row] for row in adj]


def _integral(X):
    for row in X:
        for v in row:
            if isinstance(v, int) and not isinstance(v, bool):
                continue
            if v.denominator != 1:
                return False
    return True


def _to_int(X):
    return [[int(v) for v in row] for row in X]


def _parts(M, k):
    n = len(M)
    A = [row[:k] for row in M[:k]]
    B = [row[k:] for row in M[:k]]
    C = [row[k:] for row in M[k:]]
    Ai = _inv(A)
    if Ai is None:
        return None
    AiB = _mm(Ai, B)
    S = _sub(C, _mm(_tr(B), AiB))
    P = []
    for i in range(n):
        row = []
        for j in range(n):
            if i < k and j >= k:
                row.append(-AiB[i][j - k])
            elif i == j:
                row.append(Fraction(1))
            else:
                row.append(Fraction(0))
        P.append(row)
    return A, B, C, AiB, S, P


def _blockdiag(A, S):
    k = len(A)
    m = len(S)
    out = []
    for i in range(k):
        out.append(list(A[i]) + [0] * m)
    for i in range(m):
        out.append([0] * k + list(S[i]))
    return out


def _eq(X, Y):
    if len(X) != len(Y):
        return False
    for i in range(len(X)):
        if len(X[i]) != len(Y[i]):
            return False
        for j in range(len(X[i])):
            if X[i][j] != Y[i][j]:
                return False
    return True


def _fold(M, pairs):
    n = len(M)
    used = []
    cols = []
    for pr in pairs:
        i, j = pr
        col = [0] * n
        col[i] = 1
        col[j] = 1
        cols.append(col)
        used.append(i)
        used.append(j)
    for t in range(n):
        if t not in used:
            col = [0] * n
            col[t] = 1
            cols.append(col)
    F = _tr(cols)
    return _mm(_tr(F), _mm(M, F))


def _mod2(X):
    return [[v % 2 for v in row] for row in X]


def _valid_sym(M):
    if not isinstance(M, list):
        return False
    n = len(M)
    if n == 0:
        return False
    for row in M:
        if not isinstance(row, list) or len(row) != n:
            return False
        for v in row:
            if not (isinstance(v, int) and not isinstance(v, bool)):
                return False
    for i in range(n):
        for j in range(n):
            if M[i][j] != M[j][i]:
                return False
    return True


def _valid_pairs(pairs, n):
    if not isinstance(pairs, list):
        return False
    seen = []
    for pr in pairs:
        if not isinstance(pr, list) or len(pr) != 2:
            return False
        for t in pr:
            if not (isinstance(t, int) and not isinstance(t, bool)):
                return False
            if t < 0 or t >= n or t in seen:
                return False
            seen.append(t)
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    if "expected" not in case:
        return False
    exp = case["expected"]
    if not isinstance(exp, bool):
        return False
    mode = case.get("mode")
    M = case.get("M")
    if not _valid_sym(M):
        return False
    n = len(M)
    if mode == "gf2_lift":
        Malt = case.get("M_alt")
        if not _valid_sym(Malt) or len(Malt) != n:
            return False
        pairs = case.get("pairs", [])
        if not _valid_pairs(pairs, n):
            return False
        same_mod2 = _eq(_mod2(M), _mod2(Malt))
        same_fold = _eq(_fold(M, pairs), _fold(Malt, pairs))
        prop = same_mod2 and same_fold
        return prop == exp
    if mode == "gf2_fold":
        pairs = case.get("pairs", [])
        if not _valid_pairs(pairs, n):
            return False
        FZ = _fold(M, pairs)
        F2 = _fold(_mod2(M), pairs)
        prop = _eq(_mod2(FZ), _mod2(F2))
        if prop and n <= 6:
            M2 = _mod2(M)
            for x in product((0, 1), repeat=n):
                q = 0
                for i in range(n):
                    for j in range(n):
                        q = q + M2[i][j] * x[i] * x[j]
                dsum = 0
                for i in range(n):
                    dsum = dsum + M2[i][i] * x[i]
                if q % 2 != dsum % 2:
                    prop = False
                    break
        return prop == exp
    k = case.get("k")
    if not (isinstance(k, int) and not isinstance(k, bool)):
        return False
    if k < 1 or k >= n:
        return False
    parts = _parts(M, k)
    if parts is None:
        return False
    A, B, C, AiB, S, P = parts
    lhs = _mm(_tr(P), _mm(M, P))
    exact = _eq(lhs, _blockdiag(A, S))
    if mode == "schur_integral":
        prop = exact and _integral(AiB) and _integral(S)
        return prop == exp
    if mode == "block_drop":
        prop = exact and _eq(lhs, _blockdiag(A, C))
        return prop == exp
    if mode == "scaled_congruence":
        d = _det(A)
        if d == 0 or d.denominator != 1:
            return False
        adjA_frac = _adj(A)
        if not _integral(adjA_frac):
            return False
        adjA = _to_int(adjA_frac)
        di = int(d)
        top_right = _mm(adjA, B)
        Pi = []
        for i in range(n):
            row = []
            for j in range(n):
                if i < k and j >= k:
                    row.append(-top_right[i][j - k])
                elif i == j:
                    row.append(di)
                else:
                    row.append(0)
            Pi.append(row)
        lhsi = _mm(_tr(Pi), _mm(M, Pi))
        d2 = di * di
        A2 = [[d2 * v for v in row] for row in A]
        BtAdjB = _mm(_tr(B), _mm(adjA, B))
        S2 = [[d2 * C[i][j] - di * BtAdjB[i][j] for j in range(n - k)] for i in range(n - k)]
        prop = exact and _eq(lhsi, _blockdiag(A2, S2))
        return prop == exp
    return False

def check_case(case):
    if not isinstance(case, dict):
        return False
    a = case.get('a')
    b = case.get('b')
    expected = case.get('expected')
    if not (isinstance(a, int) and not isinstance(a, bool)):
        return False
    if not (isinstance(b, int) and not isinstance(b, bool)):
        return False
    if not isinstance(expected, bool):
        return False
    actual = a != 0 and b % a == 0
    return actual == expected

from fractions import Fraction
from math import gcd, isqrt

def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _det(mat):
    k = len(mat)
    if k == 0:
        return Fraction(1)
    a = [[Fraction(x) for x in row] for row in mat]
    sign = 1
    prev = Fraction(1)
    for i in range(k - 1):
        if a[i][i] == 0:
            p = -1
            for r in range(i + 1, k):
                if a[r][i] != 0:
                    p = r
                    break
            if p < 0:
                return Fraction(0)
            a[i], a[p] = a[p], a[i]
            sign = -sign
        pv = a[i][i]
        for r in range(i + 1, k):
            for c in range(i + 1, k):
                a[r][c] = (a[r][c] * pv - a[r][i] * a[i][c]) / prev
        prev = pv
    return Fraction(sign) * a[k - 1][k - 1]

def _inv(mat):
    k = len(mat)
    aug = []
    for i in range(k):
        row = [Fraction(mat[i][j]) for j in range(k)]
        for j in range(k):
            row.append(Fraction(1 if i == j else 0))
        aug.append(row)
    for col in range(k):
        p = -1
        for r in range(col, k):
            if aug[r][col] != 0:
                p = r
                break
        if p < 0:
            return None
        aug[col], aug[p] = aug[p], aug[col]
        pv = aug[col][col]
        for c in range(2 * k):
            aug[col][c] = aug[col][c] / pv
        for r in range(k):
            if r != col and aug[r][col] != 0:
                f = aug[r][col]
                for c in range(2 * k):
                    aug[r][c] = aug[r][c] - f * aug[col][c]
    return [row[k:] for row in aug]

def _inv2(mat):
    k = len(mat)
    aug = []
    for i in range(k):
        row = [mat[i][j] % 2 for j in range(k)]
        for j in range(k):
            row.append(1 if i == j else 0)
        aug.append(row)
    for col in range(k):
        p = -1
        for r in range(col, k):
            if aug[r][col] % 2 == 1:
                p = r
                break
        if p < 0:
            return None
        aug[col], aug[p] = aug[p], aug[col]
        for r in range(k):
            if r != col and aug[r][col] % 2 == 1:
                for c in range(2 * k):
                    aug[r][c] = (aug[r][c] + aug[col][c]) % 2
    return [row[k:] for row in aug]

def _trans(mat):
    return [[mat[j][i] for j in range(len(mat))] for i in range(len(mat[0]))]

def _mul(x, y):
    n = len(x)
    p = len(y)
    m = len(y[0])
    out = [[Fraction(0) for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for k in range(p):
            if x[i][k] != 0:
                for j in range(m):
                    out[i][j] = out[i][j] + x[i][k] * y[k][j]
    return out

def _sub(x, y):
    return [[x[i][j] - y[i][j] for j in range(len(x[0]))] for i in range(len(x))]

def _eq(x, y):
    if len(x) != len(y):
        return False
    for i in range(len(x)):
        if len(x[i]) != len(y[i]):
            return False
        for j in range(len(x[i])):
            if x[i][j] != y[i][j]:
                return False
    return True

def _eq2(x, y):
    if len(x) != len(y):
        return False
    for i in range(len(x)):
        if len(x[i]) != len(y[i]):
            return False
        for j in range(len(x[i])):
            if (int(x[i][j]) % 2) != (int(y[i][j]) % 2):
                return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    for key in ('A', 'B', 'C', 'expected_q', 'expected_gf2', 'expected_mirror'):
        if key not in case:
            return False
    eq = case['expected_q']
    eg = case['expected_gf2']
    em = case['expected_mirror']
    if not (isinstance(eq, bool) and isinstance(eg, bool) and isinstance(em, bool)):
        return False
    A = case['A']
    B = case['B']
    C = case['C']
    if not isinstance(A, list) or not isinstance(B, list) or not isinstance(C, list):
        return False
    if len(A) == 0 or len(C) == 0:
        return False
    n = len(A)
    m = len(C)
    if len(B) != n:
        return False
    for i in range(n):
        if not isinstance(A[i], list) or len(A[i]) != n:
            return False
        for j in range(n):
            if not _is_int(A[i][j]):
                return False
    for i in range(n):
        if not isinstance(B[i], list) or len(B[i]) != m:
            return False
        for j in range(m):
            if not _is_int(B[i][j]):
                return False
    for i in range(m):
        if not isinstance(C[i], list) or len(C[i]) != m:
            return False
        for j in range(m):
            if not _is_int(C[i][j]):
                return False
    N = n + m
    M = [[Fraction(0) for _ in range(N)] for _ in range(N)]
    for i in range(n):
        for j in range(n):
            M[i][j] = Fraction(A[i][j])
        for j in range(m):
            M[i][n + j] = Fraction(B[i][j])
    for i in range(m):
        for j in range(n):
            M[n + i][j] = Fraction(B[j][i])
        for j in range(m):
            M[n + i][n + j] = Fraction(C[i][j])
    detA = _det(A)
    q_ok = False
    if detA != 0:
        Ai = _inv(A)
        if Ai is not None:
            Bf = [[Fraction(B[i][j]) for j in range(m)] for i in range(n)]
            X = _mul(Ai, Bf)
            L = [[Fraction(0) for _ in range(N)] for _ in range(N)]
            for i in range(n):
                L[i][i] = Fraction(1)
                for j in range(m):
                    L[i][n + j] = -X[i][j]
            for i in range(m):
                L[n + i][n + i] = Fraction(1)
            left = _mul(_mul(_trans(L), M), L)
            Bt = _trans(Bf)
            S = _sub([[Fraction(C[i][j]) for j in range(m)] for i in range(m)], _mul(_mul(Bt, Ai), Bf))
            D = [[Fraction(0) for _ in range(N)] for _ in range(N)]
            for i in range(n):
                for j in range(n):
                    D[i][j] = Fraction(A[i][j])
            for i in range(m):
                for j in range(m):
                    D[n + i][n + j] = S[i][j]
            q_ok = _eq(left, D)
    gf2_ok = False
    if detA != 0 and detA.denominator == 1 and detA.numerator % 2 != 0:
        Ai2 = _inv2(A)
        if Ai2 is not None:
            B2 = [[B[i][j] % 2 for j in range(m)] for i in range(n)]
            C2 = [[C[i][j] % 2 for j in range(m)] for i in range(m)]
            X2 = _mul(Ai2, B2)
            L2 = [[0 for _ in range(N)] for _ in range(N)]
            for i in range(n):
                L2[i][i] = 1
                for j in range(m):
                    L2[i][n + j] = int(X2[i][j]) % 2
            for i in range(m):
                L2[n + i][n + i] = 1
            M2 = [[int(M[i][j]) % 2 for j in range(N)] for i in range(N)]
            left2 = _mul(_mul(_trans(L2), M2), L2)
            Bt2 = _trans(B2)
            Y2 = _mul(Bt2, X2)
            S2 = [[(C2[i][j] + int(Y2[i][j])) % 2 for j in range(m)] for i in range(m)]
            D2 = [[0 for _ in range(N)] for _ in range(N)]
            for i in range(n):
                for j in range(n):
                    D2[i][j] = A[i][j] % 2
            for i in range(m):
                for j in range(m):
                    D2[n + i][n + j] = S2[i][j]
            gf2_ok = _eq2(left2, D2)
    detM = _det(M)
    R = [[Fraction(1 if i + j == N - 1 else 0) for j in range(N)] for i in range(N)]
    Mm = _mul(_mul(R, M), R)
    detMm = _det(Mm)
    mirror_ok = (detM == detMm)
    return q_ok == eq and gf2_ok == eg and mirror_ok == em

from fractions import Fraction
import itertools

def _int_ok(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _det(rows):
    m = len(rows)
    if m == 0:
        return 1
    if m == 1:
        return rows[0][0]
    total = 0
    for perm in itertools.permutations(range(m)):
        sign = 1
        for i in range(m):
            for j in range(i):
                if perm[j] > perm[i]:
                    sign = -sign
        prod = 1
        for i in range(m):
            prod *= rows[i][perm[i]]
        total += sign * prod
    return total

def _minor(rows, drop_i, drop_j):
    sub = []
    m = len(rows)
    for a in range(m):
        if a == drop_i:
            continue
        row = []
        for b in range(m):
            if b == drop_j:
                continue
            row.append(rows[a][b])
        sub.append(row)
    return sub

def _adj(rows):
    m = len(rows)
    cof = []
    for i in range(m):
        row = []
        for j in range(m):
            sign = 1 if (i + j) % 2 == 0 else -1
            row.append(sign * _det(_minor(rows, i, j)))
        cof.append(row)
    return [[cof[i][j] for i in range(m)] for j in range(m)]

def _mul(X, Y):
    n = len(X)
    m = len(Y[0])
    p = len(Y)
    out = []
    for i in range(n):
        row = []
        for j in range(m):
            s = Fraction(0)
            for t in range(p):
                s += X[i][t] * Y[t][j]
            row.append(s)
        out.append(row)
    return out

def _tr(X):
    return [[X[i][j] for i in range(len(X))] for j in range(len(X[0]))]

def check_case(case):
    M = case["M"]
    k = case["k"]
    if not _int_ok(k) or k < 1:
        return False
    if not isinstance(M, list) or len(M) < 2 or len(M) > 4:
        return False
    n = len(M)
    if k >= n:
        return False
    for i in range(n):
        if not isinstance(M[i], list) or len(M[i]) != n:
            return False
        for j in range(n):
            if not _int_ok(M[i][j]) or M[i][j] != M[j][i]:
                return False
    r = n - k
    A = [[M[i][j] for j in range(r)] for i in range(r)]
    B = [[M[i][r + j] for j in range(k)] for i in range(r)]
    C = [[M[r + a][r + b] for b in range(k)] for a in range(k)]
    d = _det(C)
    adj = _adj(C)
    BT = _tr(B)
    coupled = []
    for a in range(k):
        row = []
        for b in range(r):
            s = 0
            for t in range(k):
                s += adj[a][t] * BT[t][b]
            row.append(s)
        coupled.append(row)
    q_ok = d != 0
    z_ok = q_ok and all(coupled[a][b] % d == 0 for a in range(k) for b in range(r))
    gf2_ok = (d % 2) != 0
    deg = [0 for _ in range(n)]
    for i in range(n):
        for j in range(i):
            if (M[i][j] % 2) != 0:
                deg[i] += 1
                deg[j] += 1
    euler_ok = all((deg[i] % 2) == 0 for i in range(n))
    cong_ok = True
    s_int = True
    if q_ok:
        Cinv = [[Fraction(adj[a][b], d) for b in range(k)] for a in range(k)]
        BTf = [[Fraction(BT[a][b]) for b in range(r)] for a in range(k)]
        W = _mul(Cinv, BTf)
        Bf = [[Fraction(B[a][b]) for b in range(k)] for a in range(r)]
        mid = _mul(Bf, W)
        S = [[Fraction(A[i][j]) - mid[i][j] for j in range(r)] for i in range(r)]
        s_int = all(S[i][j].denominator == 1 for i in range(r) for j in range(r))
        E = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            E[i][i] = Fraction(1)
        for a in range(k):
            for b in range(r):
                E[r + a][b] = -W[a][b]
        Mf = [[Fraction(M[i][j]) for j in range(n)] for i in range(n)]
        got = _mul(_mul(_tr(E), Mf), E)
        for i in range(r):
            for j in range(r):
                if got[i][j] != S[i][j]:
                    cong_ok = False
        for a in range(k):
            for b in range(k):
                if got[r + a][r + b] != Fraction(C[a][b]):
                    cong_ok = False
        for i in range(r):
            for a in range(k):
                if got[i][r + a] != 0 or got[r + a][i] != 0:
                    cong_ok = False
        if s_int:
            S_int = [[S[i][j].numerator for j in range(r)] for i in range(r)]
            if _det(M) != _det(S_int) * d:
                cong_ok = False
    if z_ok and not s_int:
        return False
    if q_ok and not cong_ok:
        return False
    if z_ok and not q_ok:
        return False
    flags = case["flags"]
    return flags["q_congruence"] == q_ok and flags["z_congruence"] == z_ok and flags["gf2_pivot"] == gf2_ok and flags["eulerian_mirror"] == euler_ok

from fractions import Fraction
from math import gcd, isqrt


def _isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _okmat(r, rows, cols):
    if not isinstance(r, list) or len(r) != rows:
        return False
    for row in r:
        if not isinstance(row, list) or len(row) != cols:
            return False
        for v in row:
            if not _isint(v):
                return False
    return True


def _fr(r):
    return [[Fraction(v) for v in row] for row in r]


def _tr(x):
    return [list(row) for row in zip(*x)]


def _mul(x, y):
    return [[sum((x[i][t] * y[t][j] for t in range(len(y))), Fraction(0)) for j in range(len(y[0]))] for i in range(len(x))]


def _imul(x, y):
    return [[sum(x[i][t] * y[t][j] for t in range(len(y))) for j in range(len(y[0]))] for i in range(len(x))]


def _blk(P, Q, R):
    k = len(P)
    m = len(R)
    Qt = _tr(Q)
    return [P[i][:] + Q[i][:] for i in range(k)] + [Qt[j][:] + R[j][:] for j in range(m)]


def _zeros(r, c):
    return [[Fraction(0) for j in range(c)] for i in range(r)]


def _det(m):
    n = len(m)
    a = [row[:] for row in m]
    d = Fraction(1)
    for c in range(n):
        piv = None
        for r in range(c, n):
            if a[r][c] != 0:
                piv = r
                break
        if piv is None:
            return Fraction(0)
        if piv != c:
            a[c], a[piv] = a[piv], a[c]
            d = -d
        d = d * a[c][c]
        for r in range(c + 1, n):
            f = a[r][c] / a[c][c]
            if f != 0:
                for t in range(c, n):
                    a[r][t] = a[r][t] - f * a[c][t]
    return d


def _inv(m):
    n = len(m)
    a = [m[i][:] + [Fraction(1) if i == j else Fraction(0) for j in range(n)] for i in range(n)]
    for c in range(n):
        piv = None
        for r in range(c, n):
            if a[r][c] != 0:
                piv = r
                break
        if piv is None:
            return None
        a[c], a[piv] = a[piv], a[c]
        p = a[c][c]
        a[c] = [v / p for v in a[c]]
        for r in range(n):
            if r != c and a[r][c] != 0:
                f = a[r][c]
                a[r] = [a[r][t] - f * a[c][t] for t in range(2 * n)]
    return [row[n:] for row in a]


def _inv2(a):
    n = len(a)
    g = [[a[i][j] % 2 for j in range(n)] + [1 if i == j else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        piv = None
        for r in range(c, n):
            if g[r][c] == 1:
                piv = r
                break
        if piv is None:
            return None
        g[c], g[piv] = g[piv], g[c]
        for r in range(n):
            if r != c and g[r][c] == 1:
                g[r] = [(g[r][j] + g[c][j]) % 2 for j in range(2 * n)]
    return [row[n:] for row in g]


def _sym_diag(m):
    a = [row[:] for row in m]
    n = len(a)
    out = []
    idx = list(range(n))
    while idx:
        piv = None
        for i in idx:
            if a[i][i] != 0:
                piv = i
                break
        if piv is None:
            pair = None
            for i in idx:
                for j in idx:
                    if i != j and a[i][j] != 0:
                        pair = (i, j)
                        break
                if pair is not None:
                    break
            if pair is None:
                out.extend([Fraction(0)] * len(idx))
                return out
            i, j = pair
            for t in range(n):
                a[i][t] = a[i][t] + a[j][t]
            for t in range(n):
                a[t][i] = a[t][i] + a[t][j]
            piv = i
        p = a[piv][piv]
        out.append(p)
        rest = [r for r in idx if r != piv]
        for r in rest:
            f = a[r][piv] / p
            if f != 0:
                for t in range(n):
                    a[r][t] = a[r][t] - f * a[piv][t]
                for t in range(n):
                    a[t][r] = a[t][r] - f * a[t][piv]
        idx = rest
    return out


def _inertia(m):
    ds = _sym_diag(m)
    return (sum(1 for v in ds if v > 0), sum(1 for v in ds if v < 0), sum(1 for v in ds if v == 0))


def _add3(x, y):
    return (x[0] + y[0], x[1] + y[1], x[2] + y[2])


def _is_sq(q):
    if q < 0:
        return False
    n = q.numerator
    d = q.denominator
    return isqrt(n) ** 2 == n and isqrt(d) ** 2 == d


def _same_class(x, y):
    if x == 0 or y == 0:
        return x == 0 and y == 0
    return _is_sq(x * y)


def _mirror_curves(p, q):
    w = 2 * p
    h = 2 * q
    states = []
    for x in range(w + 1):
        for y in range(h + 1):
            if (x + y) % 2 == 1:
                for dx in (1, -1):
                    for dy in (1, -1):
                        if 0 <= x + dx <= w and 0 <= y + dy <= h:
                            states.append((x, y, dx, dy))
    if len(states) != 8 * p * q:
        return -1
    seen = set()
    cycles = 0
    for s in states:
        if s in seen:
            continue
        cycles += 1
        cur = s
        while cur not in seen:
            seen.add(cur)
            x, y, dx, dy = cur
            nx = x + dx
            ny = y + dy
            if nx == 0 or nx == w:
                dx = -dx
            if ny == 0 or ny == h:
                dy = -dy
            cur = (nx, ny, dx, dy)
        if cur != s:
            return -1
    if cycles % 2 != 0:
        return -1
    return cycles // 2


def _predict(case):
    mode = case.get('mode')
    if mode == 'mirror':
        p = case.get('p')
        q = case.get('q')
        if not (_isint(p) and _isint(q)) or p < 1 or q < 1:
            return None
        c = _mirror_curves(p, q)
        if c < 0:
            return None
        claim = case.get('claim')
        if claim == 'count':
            return c == gcd(p, q)
        if claim == 'eulerian':
            return c == 1
        if claim == 'single_shear':
            return (c == 1) == (q % p == 0)
        return None
    Ar = case.get('A')
    Br = case.get('B')
    Dr = case.get('D')
    if not isinstance(Ar, list) or not isinstance(Dr, list):
        return None
    k = len(Ar)
    m = len(Dr)
    if k < 1 or m < 1 or not _okmat(Ar, k, k) or not _okmat(Br, k, m) or not _okmat(Dr, m, m):
        return None
    A = _fr(Ar)
    B = _fr(Br)
    D = _fr(Dr)
    if A != _tr(A) or D != _tr(D):
        return None
    M = _blk(A, B, D)
    dA = _det(A)
    if dA == 0:
        return False
    X = _mul(_inv(A), B)
    BtX = _mul(_tr(B), X)
    S = [[D[i][j] - BtX[i][j] for j in range(m)] for i in range(m)]
    if mode == 'schur_q':
        n = k + m
        L = [[Fraction(1) if i == j else Fraction(0) for j in range(n)] for i in range(n)]
        for i in range(k):
            for j in range(m):
                L[i][k + j] = -X[i][j]
        C = _mul(_mul(_tr(L), M), L)
        Z = _blk(A, _zeros(k, m), S)
        ok1 = C == Z
        ok2 = _det(M) == dA * _det(S)
        ok3 = _inertia(M) == _add3(_inertia(A), _inertia(S))
        return ok1 and ok2 and ok3
    if mode == 'schur_z':
        xint = all(v.denominator == 1 for row in X for v in row)
        sint = all(v.denominator == 1 for row in S for v in row)
        if xint and not sint:
            return None
        return xint
    if mode == 'block_q':
        if m != 1:
            return None
        d = D[0][0]
        s = S[0][0]
        pred = _same_class(d, s)
        AD = _blk(A, _zeros(k, 1), D)
        inv_eq = _inertia(M) == _inertia(AD)
        sq_eq = _same_class(_det(M), _det(AD))
        complete = inv_eq and sq_eq
        if pred != complete:
            return None
        iso = all(v == 0 for row in BtX for v in row)
        if iso and not pred:
            return None
        return pred
    if mode == 'gf2_fold':
        if dA.numerator % 2 == 0:
            return False
        if any(v.denominator % 2 == 0 for row in S for v in row):
            return None
        Ai2 = _inv2(Ar)
        if Ai2 is None:
            return None
        T = _imul(_imul(_tr(Br), Ai2), Br)
        Sg = [[(Dr[i][j] + T[i][j]) % 2 for j in range(m)] for i in range(m)]
        Sm = [[S[i][j].numerator % 2 for j in range(m)] for i in range(m)]
        if Sm != Sg:
            return None
        if all(M[i][i].numerator % 2 == 0 for i in range(k + m)):
            if any(S[i][i].numerator % 2 != 0 for i in range(m)):
                return None
        return True
    return None


def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get('expected')
    if not isinstance(exp, bool):
        return False
    try:
        pred = _predict(case)
    except Exception:
        return False
    if not isinstance(pred, bool):
        return False
    return pred == exp

from fractions import Fraction
from math import gcd


def _T(X):
    return [list(r) for r in zip(*X)]


def _mul(X, Y):
    n = len(X)
    k = len(Y)
    m = len(Y[0])
    return [[sum(X[i][t] * Y[t][j] for t in range(k)) for j in range(m)] for i in range(n)]


def _det(M):
    n = len(M)
    if n == 0:
        return 1
    A = [r[:] for r in M]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if A[k][k] == 0:
            r = k + 1
            while r < n and A[r][k] == 0:
                r += 1
            if r == n:
                return 0
            A[k], A[r] = A[r], A[k]
            sign = -sign
        piv = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * piv - A[i][k] * A[k][j]) // prev
            A[i][k] = 0
        prev = piv
    return sign * A[n - 1][n - 1]


def _adj(A):
    n = len(A)
    if n == 1:
        return [[1]]
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            minor = [[A[r][c] for c in range(n) if c != j] for r in range(n) if r != i]
            v = _det(minor)
            if (i + j) % 2 == 1:
                v = -v
            C[i][j] = v
    return _T(C)


def _blocks(A, B, D):
    top = [A[i] + B[i] for i in range(len(A))]
    Bt = _T(B)
    bot = [Bt[i] + D[i] for i in range(len(D))]
    return top + bot


def _diag2(X, Y):
    k = len(X)
    m = len(Y)
    Z = [[0] * (k + m) for _ in range(k + m)]
    for i in range(k):
        for j in range(k):
            Z[i][j] = X[i][j]
    for i in range(m):
        for j in range(m):
            Z[k + i][k + j] = Y[i][j]
    return Z


def _schur_data(A, B, D):
    d = _det(A)
    if d == 0:
        return None
    adj = _adj(A)
    Ainv = [[Fraction(adj[i][j], d) for j in range(len(A))] for i in range(len(A))]
    K = _mul(Ainv, B)
    T = _mul(_mul(_T(B), Ainv), B)
    S = [[Fraction(D[i][j]) - T[i][j] for j in range(len(D[0]))] for i in range(len(D))]
    return d, adj, K, S, T


def _q_ok(A, B, D):
    data = _schur_data(A, B, D)
    if data is None:
        return False
    d, adj, K, S, T = data
    k = len(A)
    m = len(D)
    P = [[Fraction(0)] * (k + m) for _ in range(k + m)]
    for i in range(k + m):
        P[i][i] = Fraction(1)
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -K[i][j]
    M = _blocks(A, B, D)
    lhs = _mul(_mul(_T(P), M), P)
    rhs = _diag2([[Fraction(x) for x in r] for r in A], S)
    return lhs == rhs


def _z_ok(A, B, D):
    data = _schur_data(A, B, D)
    if data is None:
        return False
    d, adj, K, S, T = data
    adjB = _mul(adj, B)
    for i in range(len(adjB)):
        for j in range(len(adjB[0])):
            if adjB[i][j] % d != 0:
                return False
    Kint = [[adjB[i][j] // d for j in range(len(adjB[0]))] for i in range(len(adjB))]
    k = len(A)
    m = len(D)
    P = [[0] * (k + m) for _ in range(k + m)]
    for i in range(k + m):
        P[i][i] = 1
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -Kint[i][j]
    M = _blocks(A, B, D)
    lhs = _mul(_mul(_T(P), M), P)
    BtK = _mul(_T(B), Kint)
    S_int = [[D[i][j] - BtK[i][j] for j in range(m)] for i in range(m)]
    rhs = _diag2(A, S_int)
    return lhs == rhs


def _scaled_ok(A, B, D):
    data = _schur_data(A, B, D)
    if data is None:
        return False
    d, adj, K, S, T = data
    k = len(A)
    m = len(D)
    adjB = _mul(adj, B)
    P = [[0] * (k + m) for _ in range(k + m)]
    for i in range(k):
        P[i][i] = d
    for i in range(m):
        P[k + i][k + i] = d
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -adjB[i][j]
    M = _blocks(A, B, D)
    lhs = _mul(_mul(_T(P), M), P)
    BtAdjB = _mul(_mul(_T(B), adj), B)
    top = [[d * d * A[i][j] for j in range(k)] for i in range(k)]
    bot = [[d * d * D[i][j] - d * BtAdjB[i][j] for j in range(m)] for i in range(m)]
    return lhs == _diag2(top, bot)


def _block_ok(A, B, D):
    data = _schur_data(A, B, D)
    if data is None:
        return False
    d, adj, K, S, T = data
    for i in range(len(T)):
        for j in range(len(T[0])):
            if T[i][j] != 0:
                return False
    return True


def _gf2_ok(A, B, D):
    d = _det(A)
    if d % 2 == 0:
        return False
    data = _schur_data(A, B, D)
    if data is None:
        return False
    d, adj, K, S, T = data
    adj2 = [[adj[i][j] % 2 for j in range(len(adj[0]))] for i in range(len(adj))]
    B2 = [[B[i][j] % 2 for j in range(len(B[0]))] for i in range(len(B))]
    D2 = [[D[i][j] % 2 for j in range(len(D[0]))] for i in range(len(D))]
    T2 = _mul(_mul(_T(B2), adj2), B2)
    ok = True
    for i in range(len(S)):
        for j in range(len(S[0])):
            f = S[i][j]
            if f.denominator % 2 == 0:
                return False
            red = f.numerator % 2
            s2 = (D2[i][j] + T2[i][j]) % 2
            if red != s2:
                ok = False
    return ok


def _mirror_count(p, q):
    if not isinstance(p, int) or isinstance(p, bool) or p < 1:
        return -1
    if not isinstance(q, int) or isinstance(q, bool) or q < 1:
        return -1
    W = 2 * p
    H = 2 * q
    states = []
    for x in range(W + 1):
        for y in range(H + 1):
            if (x + y) % 2 == 1:
                for dx in (-1, 1):
                    if x == 0 and dx == -1:
                        continue
                    if x == W and dx == 1:
                        continue
                    for dy in (-1, 1):
                        if y == 0 and dy == -1:
                            continue
                        if y == H and dy == 1:
                            continue
                        states.append((x, y, dx, dy))
    seen = set()
    cycles = 0
    for s in states:
        if s in seen:
            continue
        cycles += 1
        t = s
        while t not in seen:
            seen.add(t)
            x, y, dx, dy = t
            nx = x + dx
            ny = y + dy
            ndx = dx
            ndy = dy
            if nx == 0:
                ndx = 1
            elif nx == W:
                ndx = -1
            if ny == 0:
                ndy = 1
            elif ny == H:
                ndy = -1
            t = (nx, ny, ndx, ndy)
    return cycles // 2


def check_case(case):
    if not isinstance(case, dict):
        return False
    expected = case.get("expected")
    if not isinstance(expected, bool):
        return False
    mode = case.get("mode")
    if mode == "mirror_curve":
        p = case.get("p")
        q = case.get("q")
        cnt = _mirror_count(p, q)
        if cnt < 0:
            return False
        pred = (cnt == gcd(p, q))
        return bool(pred == expected)
    A = case.get("A")
    B = case.get("B")
    D = case.get("D")
    if D is None:
        D = case.get("C")
    if not isinstance(A, list) or not isinstance(B, list) or not isinstance(D, list):
        return False
    if len(A) == 0 or len(B) == 0 or len(D) == 0:
        return False
    if mode == "schur_q":
        pred = _q_ok(A, B, D)
    elif mode == "schur_z":
        pred = _z_ok(A, B, D)
    elif mode == "scaled_z":
        pred = _scaled_ok(A, B, D)
    elif mode == "block_only" or mode == "block_drop":
        pred = _block_ok(A, B, D)
    elif mode == "gf2_fold":
        pred = _gf2_ok(A, B, D)
    else:
        return False
    return bool(pred == expected)

from fractions import Fraction
from math import gcd
from itertools import permutations

def det(a):
    n = len(a)
    total = 0
    for p in permutations(range(n)):
        inversions = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inversions += 1
        term = 1
        for i in range(n):
            term *= a[i][p[i]]
        if inversions % 2:
            total -= term
        else:
            total += term
    return total

def inverse(a):
    n = len(a)
    rows = []
    for i in range(n):
        row = [Fraction(a[i][j]) for j in range(n)]
        for j in range(n):
            row.append(Fraction(1 if i == j else 0))
        rows.append(row)
    for col in range(n):
        pivot = col
        while pivot < n and rows[pivot][col] == 0:
            pivot += 1
        if pivot == n:
            return None
        rows[col], rows[pivot] = rows[pivot], rows[col]
        scale = rows[col][col]
        rows[col] = [x / scale for x in rows[col]]
        for r in range(n):
            if r != col:
                scale = rows[r][col]
                rows[r] = [rows[r][j] - scale * rows[col][j] for j in range(2 * n)]
    return [row[n:] for row in rows]

def transpose(a):
    return [[a[i][j] for i in range(len(a))] for j in range(len(a[0]))]

def multiply(a, b):
    return [[sum(a[i][k] * b[k][j] for k in range(len(b))) for j in range(len(b[0]))] for i in range(len(a))]

def check_case(case):
    if not isinstance(case, dict) or not isinstance(case.get("expected"), bool):
        return False
    mode = case.get("mode")
    if mode == "mirror_curves":
        prediction = gcd(case["p"], case["q"]) == case["components"]
    elif mode == "mirror_lift":
        a = case["left"]
        b = case["right"]
        same_mod2 = all(a[i][j] % 2 == b[i][j] % 2 for i in range(2) for j in range(2))
        left_fold = a[0][0] + 2 * a[0][1] + a[1][1]
        right_fold = b[0][0] + 2 * b[0][1] + b[1][1]
        prediction = (not same_mod2) or left_fold == right_fold
    else:
        a = case["A"]
        b = case["B"]
        d = case["D"]
        determinant = det(a)
        if mode == "schur_q":
            prediction = determinant != 0
        elif mode == "schur_z":
            inv = inverse(a)
            prediction = inv is not None and all(x.denominator == 1 for row in multiply(inv, b) for x in row)
        elif mode == "block_drop":
            inv = inverse(a)
            if inv is None:
                prediction = False
            else:
                correction = multiply(transpose(b), multiply(inv, b))
                prediction = all(x == 0 for row in correction for x in row)
        elif mode == "gf2":
            prediction = determinant % 2 == 1
        else:
            return False
    return prediction == case["expected"]

from fractions import Fraction
from math import gcd


def _det_fr(M):
    n = len(M)
    a = [[Fraction(M[i][j]) for j in range(n)] for i in range(n)]
    det = Fraction(1)
    for c in range(n):
        piv = None
        for r in range(c, n):
            if a[r][c] != 0:
                piv = r
                break
        if piv is None:
            return Fraction(0)
        if piv != c:
            a[c], a[piv] = a[piv], a[c]
            det = -det
        det = det * a[c][c]
        inv = a[c][c]
        for r in range(c + 1, n):
            f = a[r][c] / inv
            if f != 0:
                for j in range(c, n):
                    a[r][j] = a[r][j] - f * a[c][j]
    return det


def _det_int(M):
    d = _det_fr(M)
    if d.denominator != 1:
        return None
    return d.numerator


def _transpose(M):
    return [[M[i][j] for i in range(len(M))] for j in range(len(M[0]))]


def _mul(X, Y):
    n = len(X)
    k = len(Y)
    m = len(Y[0])
    out = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            s = 0
            for t in range(k):
                s = s + X[i][t] * Y[t][j]
            out[i][j] = s
    return out


def _minor(M, i, j):
    return [[M[r][c] for c in range(len(M)) if c != j] for r in range(len(M)) if r != i]


def _adj(M):
    n = len(M)
    if n == 1:
        return [[1]]
    out = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            v = _det_int(_minor(M, j, i))
            if (i + j) % 2 == 1:
                v = -v
            out[i][j] = v
    return out


def _rank(M):
    a = [[Fraction(v) for v in row] for row in M]
    rows = len(a)
    cols = len(a[0])
    r = 0
    for c in range(cols):
        piv = None
        for i in range(r, rows):
            if a[i][c] != 0:
                piv = i
                break
        if piv is None:
            continue
        a[r], a[piv] = a[piv], a[r]
        inv = a[r][c]
        for i in range(r + 1, rows):
            f = a[i][c] / inv
            if f != 0:
                for j in range(c, cols):
                    a[i][j] = a[i][j] - f * a[r][j]
        r = r + 1
        if r == rows:
            break
    return r


def _blocks(A, B, C):
    k = len(A)
    m = len(C)
    M = [[0] * (k + m) for _ in range(k + m)]
    for i in range(k):
        for j in range(k):
            M[i][j] = A[i][j]
        for j in range(m):
            M[i][k + j] = B[i][j]
            M[k + j][i] = B[i][j]
    for i in range(m):
        for j in range(m):
            M[k + i][k + j] = C[i][j]
    return M


def _inv2(A):
    n = len(A)
    aug = [[A[i][j] % 2 for j in range(n)] + [1 if i == j else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        piv = None
        for r in range(c, n):
            if aug[r][c] % 2 == 1:
                piv = r
                break
        if piv is None:
            return None
        aug[c], aug[piv] = aug[piv], aug[c]
        for r in range(n):
            if r != c and aug[r][c] % 2 == 1:
                for j in range(c, 2 * n):
                    aug[r][j] = (aug[r][j] + aug[c][j]) % 2
    return [[aug[i][n + j] % 2 for j in range(n)] for i in range(n)]


def _fold(M, k):
    n = len(M)
    m = n - k
    A = [[M[i][j] for j in range(k)] for i in range(k)]
    B = [[M[i][k + j] for j in range(m)] for i in range(k)]
    C = [[M[k + i][k + j] for j in range(m)] for i in range(m)]
    d = _det_int(A)
    if d == 0:
        return None
    T = _mul(_mul(_transpose(B), _adj(A)), B)
    return [[d * C[i][j] - T[i][j] for j in range(m)] for i in range(m)]


def check_case(case):
    mode = case['mode']
    if mode == 'mirror':
        p = case['p']
        q = case['q']
        predict = (gcd(p, q) == 1)
        return bool(predict == case['expected'])
    if mode == 'gf2_lift':
        f1 = _fold(case['M1'], 1)
        f2 = _fold(case['M2'], 1)
        i1 = [[v % 2 for v in row] for row in case['M1']]
        i2 = [[v % 2 for v in row] for row in case['M2']]
        if i1 != i2:
            predict = True
        else:
            predict = (f1 == f2)
        return bool(predict == case['expected'])
    A = case['A']
    B = case['B']
    C = case['C']
    k = len(A)
    m = len(C)
    d = _det_int(A)
    if mode == 'canonical_z':
        if d == 0:
            predict = False
        else:
            prod = _mul(_adj(A), B)
            predict = all(v % d == 0 for row in prod for v in row)
        return bool(predict == case['expected'])
    if mode == 'scaled_z':
        if d == 0:
            predict = False
        else:
            adjA = _adj(A)
            E = _mul(adjA, B)
            P = [[0] * (k + m) for _ in range(k + m)]
            for i in range(k):
                P[i][i] = d
                for j in range(m):
                    P[i][k + j] = -E[i][j]
            for i in range(m):
                P[k + i][k + i] = d
            M = _blocks(A, B, C)
            lhs = _mul(_mul(_transpose(P), M), P)
            T = _mul(_mul(_transpose(B), adjA), B)
            target = [[0] * (k + m) for _ in range(k + m)]
            for i in range(k):
                for j in range(k):
                    target[i][j] = d * d * A[i][j]
            for i in range(m):
                for j in range(m):
                    target[k + i][k + j] = d * d * C[i][j] - d * T[i][j]
            predict = (lhs == target) and (_det_int(P) == d ** (k + m))
        return bool(predict == case['expected'])
    if mode == 'block_drop':
        if d == 0:
            predict = False
        else:
            T = _mul(_mul(_transpose(B), _adj(A)), B)
            iso = all(v == 0 for row in T for v in row)
            M = _blocks(A, B, C)
            blk = _blocks(A, [[0] * m for _ in range(k)], C)
            predict = iso and (_rank(M) == _rank(blk)) and (_det_int(M) == d * _det_int(C))
        return bool(predict == case['expected'])
    if mode == 'gf2_fold':
        if d == 0:
            predict = False
        else:
            Ainv = _inv2(A)
            if Ainv is None or d % 2 == 0:
                predict = False
            else:
                B2 = [[v % 2 for v in row] for row in B]
                C2 = [[v % 2 for v in row] for row in C]
                s2 = _mul(_mul(_transpose(B2), Ainv), B2)
                schur2 = [[(C2[i][j] + s2[i][j]) % 2 for j in range(m)] for i in range(m)]
                T = _mul(_mul(_transpose(B), _adj(A)), B)
                scaled2 = [[(d * d * C[i][j] - d * T[i][j]) % 2 for j in range(m)] for i in range(m)]
                predict = (schur2 == scaled2)
        return bool(predict == case['expected'])
    return False

from fractions import Fraction
from math import gcd

def _det(m):
    n = len(m)
    a = [[Fraction(x) for x in row] for row in m]
    det = Fraction(1)
    for i in range(n):
        piv = -1
        for r in range(i, n):
            if a[r][i] != 0:
                piv = r
                break
        if piv == -1:
            return 0
        if piv != i:
            a[i], a[piv] = a[piv], a[i]
            det = -det
        det = det * a[i][i]
        inv = Fraction(1) / a[i][i]
        for r in range(i + 1, n):
            f = a[r][i] * inv
            if f != 0:
                for c in range(i, n):
                    a[r][c] = a[r][c] - f * a[i][c]
    return det

def _matmul(x, y):
    n = len(x)
    k = len(y)
    m = len(y[0])
    out = [[Fraction(0) for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            s = Fraction(0)
            for t in range(k):
                s = s + x[i][t] * y[t][j]
            out[i][j] = s
    return out

def _transpose(x):
    return [[x[i][j] for i in range(len(x))] for j in range(len(x[0]))]

def _sub(x, y):
    return [[x[i][j] - y[i][j] for j in range(len(x[0]))] for i in range(len(x))]

def _inv(a):
    n = len(a)
    aug = [[Fraction(a[i][j]) for j in range(n)] + [Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    for col in range(n):
        piv = -1
        for r in range(col, n):
            if aug[r][col] != 0:
                piv = r
                break
        if piv == -1:
            return None
        if piv != col:
            aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        invp = Fraction(1) / pv
        for j in range(2 * n):
            aug[col][j] = aug[col][j] * invp
        for r in range(n):
            if r != col and aug[r][col] != 0:
                f = aug[r][col]
                for j in range(2 * n):
                    aug[r][j] = aug[r][j] - f * aug[col][j]
    return [row[n:] for row in aug]

def _integral(x):
    if isinstance(x, bool):
        return False
    if isinstance(x, int):
        return True
    if isinstance(x, Fraction):
        return x.denominator == 1
    return False

def _all_int(m):
    return all(_integral(x) for row in m for x in row)

def _eq(x, y):
    if len(x) != len(y):
        return False
    for i in range(len(x)):
        if len(x[i]) != len(y[i]):
            return False
        for j in range(len(x[i])):
            if x[i][j] != y[i][j]:
                return False
    return True

def _schur(A, B, D):
    inv = _inv(A)
    if inv is None:
        return None
    return _sub(D, _matmul(_matmul(_transpose(B), inv), B))

def check_case(case):
    mode = case['mode']
    if mode == 'schur_q':
        pred = _det(case['A']) != 0
    elif mode == 'shear_z':
        inv = _inv(case['A'])
        pred = inv is not None and _all_int(_matmul(inv, case['B']))
    elif mode == 'block_only':
        inv = _inv(case['A'])
        if inv is None:
            pred = False
        else:
            S = _schur(case['A'], case['B'], case['D'])
            pred = S is not None and _eq(S, case['D'])
    elif mode == 'gf2_fold':
        d = _det(case['A'])
        pred = isinstance(d, Fraction) and d.denominator == 1 and (d.numerator % 2) == 1
    elif mode == 'mirror_single':
        pred = gcd(case['p'], case['q']) == 1
    elif mode == 'gf2_lift_gap':
        m1 = case['M1']
        m2 = case['M2']
        same_mod2 = all(((m1[i][j] - m2[i][j]) % 2) == 0 for i in range(len(m1)) for j in range(len(m1[0])))
        diff_z = _det(m1) != _det(m2)
        pred = same_mod2 and diff_z
    else:
        pred = False
    return pred == case['expected']

from fractions import Fraction

def mat(rows):
    return [[Fraction(v) for v in row] for row in rows]

def eye(n):
    return [[Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]

def zeros(r, c):
    return [[Fraction(0) for j in range(c)] for i in range(r)]

def trans(X):
    return [[X[i][j] for i in range(len(X))] for j in range(len(X[0]))]

def mm(X, Y):
    return [[sum(X[i][k] * Y[k][j] for k in range(len(Y))) for j in range(len(Y[0]))] for i in range(len(X))]

def sub(X, Y):
    return [[X[i][j] - Y[i][j] for j in range(len(X[0]))] for i in range(len(X))]

def blocks(A, B, C, D):
    return [A[i] + B[i] for i in range(len(A))] + [C[i] + D[i] for i in range(len(C))]

def det(X):
    n = len(X)
    Y = [row[:] for row in X]
    value = Fraction(1)
    for k in range(n):
        p = k
        while p < n and Y[p][k] == 0:
            p += 1
        if p == n:
            return Fraction(0)
        if p != k:
            Y[k], Y[p] = Y[p], Y[k]
            value = -value
        pivot = Y[k][k]
        value *= pivot
        for i in range(k + 1, n):
            q = Y[i][k] / pivot
            for j in range(k + 1, n):
                Y[i][j] -= q * Y[k][j]
    return value

def inv(X):
    n = len(X)
    E = eye(n)
    Y = [X[i][:] + E[i][:] for i in range(n)]
    for k in range(n):
        p = k
        while p < n and Y[p][k] == 0:
            p += 1
        if p == n:
            return None
        if p != k:
            Y[k], Y[p] = Y[p], Y[k]
        pivot = Y[k][k]
        Y[k] = [v / pivot for v in Y[k]]
        for i in range(n):
            if i != k:
                q = Y[i][k]
                for j in range(2 * n):
                    Y[i][j] -= q * Y[k][j]
    return [row[n:] for row in Y]

def integral(X):
    return all(v.denominator == 1 for row in X for v in row)

def reduce2(X):
    for row in X:
        for v in row:
            if v.denominator % 2 == 0:
                return None
    return [[v.numerator % 2 for v in row] for row in X]

def positive(X):
    n = len(X)
    for i in range(n):
        for j in range(n):
            if X[i][j] != X[j][i]:
                return False
    Y = [row[:] for row in X]
    for k in range(n):
        pivot = Y[k][k]
        if pivot <= 0:
            return False
        for i in range(k + 1, n):
            q = Y[i][k] / pivot
            for j in range(k + 1, n):
                Y[i][j] -= q * Y[k][j]
    return True

def check_case(case):
    mode = case['mode']
    if mode == 'gf2_loewner':
        M = mat(case['M'])
        N = mat(case['N'])
        same_parity = reduce2(M) == reduce2(N)
        prediction = (not same_parity) or (positive(M) == positive(N))
        return bool(prediction) == case['expected']
    A = mat(case['A'])
    B = mat(case['B'])
    D = mat(case['D'])
    k = len(A)
    ell = len(D)
    M = blocks(A, B, trans(B), D)
    detA = det(A)
    ok = False
    if detA != 0:
        AI = inv(A)
        X = mm(AI, B)
        correction = mm(trans(B), X)
        S = sub(D, correction)
        P = blocks(eye(k), [[-v for v in row] for row in X], zeros(ell, k), eye(ell))
        image = mm(trans(P), mm(M, P))
        target = blocks(A, zeros(k, ell), zeros(ell, k), S)
        cong = image == target and det(P) == 1
        detlaw = det(M) == detA * det(S)
        if mode == 'schur_q':
            ok = cong and detlaw
        elif mode == 'schur_z':
            ok = cong and detlaw and integral(X) and integral(S)
        elif mode == 'block_drop':
            drop = blocks(A, zeros(k, ell), zeros(ell, k), D)
            ok = cong and correction == zeros(ell, ell) and image == drop
        elif mode == 'gf2_fold' and detA.numerator % 2 == 1:
            A2 = mat(reduce2(A))
            B2 = mat(reduce2(B))
            D2 = mat(reduce2(D))
            AI2 = inv(A2)
            rhs = sub(D2, mm(trans(B2), mm(AI2, B2)))
            left = reduce2(S)
            right = reduce2(rhs)
            ok = cong and detlaw and left is not None and right is not None and left == right
    return bool(ok) == case['expected']

from fractions import Fraction
from math import gcd, isqrt

def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _mat(rows):
    out = []
    for row in rows:
        r = []
        for x in row:
            if not _is_int(x):
                return None
            r.append(x)
        out.append(r)
    if len(out) == 0:
        return None
    w = len(out[0])
    if w == 0:
        return None
    for r in out:
        if len(r) != w:
            return None
    return out

def _zeros(n, m):
    return [[0 for _ in range(m)] for _ in range(n)]

def _transpose(M):
    return [[M[i][j] for i in range(len(M))] for j in range(len(M[0]))]

def _mul(A, B):
    n = len(A)
    p = len(B)
    m = len(B[0])
    C = _zeros(n, m)
    for i in range(n):
        for k in range(p):
            aik = A[i][k]
            if aik == 0:
                continue
            for j in range(m):
                C[i][j] += aik * B[k][j]
    return C

def _det(A):
    n = len(A)
    if n == 1:
        return A[0][0]
    if n == 2:
        return A[0][0] * A[1][1] - A[0][1] * A[1][0]
    s = 0
    for j in range(n):
        sign = 1 if (j % 2 == 0) else -1
        minor = []
        for i in range(1, n):
            row = []
            for k in range(n):
                if k != j:
                    row.append(A[i][k])
            minor.append(row)
        s += sign * A[0][j] * _det(minor)
    return s

def _adj(A):
    n = len(A)
    if n == 1:
        return [[1]]
    C = _zeros(n, n)
    for i in range(n):
        for j in range(n):
            minor = []
            for r in range(n):
                if r == i:
                    continue
                row = []
                for c in range(n):
                    if c == j:
                        continue
                    row.append(A[r][c])
                minor.append(row)
            sign = 1 if ((i + j) % 2 == 0) else -1
            C[j][i] = sign * _det(minor)
    return C

def _symmetric(M):
    n = len(M)
    if len(M[0]) != n:
        return False
    for i in range(n):
        for j in range(n):
            if M[i][j] != M[j][i]:
                return False
    return True

def _divides(d, M):
    if d == 0:
        return False
    for row in M:
        for x in row:
            if x % d != 0:
                return False
    return True

def _is_square(k):
    if k < 0:
        return False
    r = isqrt(k)
    return r * r == k

def _ratio_is_square(num, den):
    if den == 0:
        return False
    if den < 0:
        num = -num
        den = -den
    if num < 0:
        return False
    g = gcd(num, den)
    num = num // g
    den = den // g
    return _is_square(num) and _is_square(den)

def _assemble(A, B, D):
    n = len(A)
    m = len(D)
    N = n + m
    M = _zeros(N, N)
    for i in range(n):
        for j in range(n):
            M[i][j] = A[i][j]
    for i in range(n):
        for j in range(m):
            M[i][n + j] = B[i][j]
            M[n + j][i] = B[i][j]
    for i in range(m):
        for j in range(m):
            M[n + i][n + j] = D[i][j]
    return M

def _sign(x):
    if x > 0:
        return 1
    if x < 0:
        return -1
    return 0

def _sig2(a, b, c):
    detv = a * c - b * b
    if a == 0 and b == 0 and c == 0:
        return (0, 0, 2)
    piv = []
    if a != 0:
        piv.append(a)
        if detv == 0:
            piv.append(0)
        else:
            piv.append(detv * a)
    elif c != 0:
        piv.append(c)
        if detv == 0:
            piv.append(0)
        else:
            piv.append(detv * c)
    else:
        return (1, 1, 0)
    np = 0
    nn = 0
    nz = 0
    for p in piv:
        s = _sign(p)
        if s > 0:
            np += 1
        elif s < 0:
            nn += 1
        else:
            nz += 1
    return (np, nn, nz)

def _predict(mode, A, B, D):
    if not _symmetric(A) or not _symmetric(D):
        return False
    n = len(A)
    m = len(D)
    if len(B) != n or len(B[0]) != m:
        return False
    d = _det(A)
    Adj = _adj(A)
    AB = _mul(Adj, B)
    if mode == 'schur_q':
        return d != 0
    if mode == 'schur_z':
        return d != 0 and _divides(d, AB)
    if mode == 'gf2':
        return (d % 2) != 0
    if mode == 'block_drop':
        if d == 0:
            return False
        mid = _mul(_transpose(B), AB)
        for row in mid:
            for x in row:
                if x != 0:
                    return False
        return True
    if mode == 'scaled':
        if d == 0:
            return False
        BT = _transpose(B)
        mid = _mul(BT, AB)
        N = n + m
        P = _zeros(N, N)
        for i in range(n):
            P[i][i] = d
        for i in range(m):
            P[n + i][n + i] = d
        for i in range(n):
            for j in range(m):
                P[i][n + j] = -AB[i][j]
        M = _assemble(A, B, D)
        R = _mul(_transpose(P), _mul(M, P))
        for i in range(n):
            for j in range(n):
                if R[i][j] != d * d * A[i][j]:
                    return False
        for i in range(m):
            for j in range(m):
                if R[n + i][n + j] != d * d * D[i][j] - d * mid[i][j]:
                    return False
        for i in range(n):
            for j in range(m):
                if R[i][n + j] != 0 or R[n + j][i] != 0:
                    return False
        return True
    if mode == 'det_class_agrees':
        if d == 0:
            return False
        M = _assemble(A, B, D)
        detM = _det(M)
        detAD = d * _det(D)
        return _ratio_is_square(detM, detAD)
    if mode == 'inertia_agrees':
        if n != 1 or m != 1:
            return False
        a = A[0][0]
        b = B[0][0]
        c = D[0][0]
        return _sig2(a, b, c) == _sig2(a, 0, c)
    return False

def check_case(case):
    A = _mat(case['A'])
    B = _mat(case['B'])
    D = _mat(case['D'])
    if A is None or B is None or D is None:
        return False
    expected = case['expected']
    if not isinstance(expected, bool):
        return False
    pred = _predict(case['mode'], A, B, D)
    return pred == expected

from fractions import Fraction
from math import gcd, isqrt


def _isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _ok_mat(R):
    if not isinstance(R, list) or len(R) == 0 or len(R) > 6:
        return False
    w = None
    for r in R:
        if not isinstance(r, list) or len(r) == 0:
            return False
        if w is None:
            w = len(r)
        if len(r) != w:
            return False
        for v in r:
            if not _isint(v):
                return False
    return True


def _tr(X):
    return [[X[i][j] for i in range(len(X))] for j in range(len(X[0]))]


def _mul(X, Y):
    t = len(Y)
    return [[sum((X[i][s] * Y[s][j] for s in range(t)), Fraction(0)) for j in range(len(Y[0]))] for i in range(len(X))]


def _ident(n):
    return [[Fraction(1) if i == j else Fraction(0) for j in range(n)] for i in range(n)]


def _zeros(r, c):
    return [[Fraction(0) for j in range(c)] for i in range(r)]


def _neg(X):
    return [[-v for v in r] for r in X]


def _scal(c, X):
    return [[c * v for v in r] for r in X]


def _is_intmat(X):
    return all(v.denominator == 1 for r in X for v in r)


def _join(P11, P12, P21, P22):
    return [P11[i] + P12[i] for i in range(len(P11))] + [P21[j] + P22[j] for j in range(len(P21))]


def _blocks(A, B, D):
    return _join(A, B, _tr(B), D)


def _congr(P, M):
    return _mul(_mul(_tr(P), M), P)


def _det_inv(A):
    n = len(A)
    I = _ident(n)
    W = [list(A[i]) + I[i] for i in range(n)]
    det = Fraction(1)
    for c in range(n):
        piv = None
        for r in range(c, n):
            if W[r][c] != 0:
                piv = r
                break
        if piv is None:
            return Fraction(0), None
        if piv != c:
            W[c], W[piv] = W[piv], W[c]
            det = -det
        pv = W[c][c]
        det = det * pv
        W[c] = [v / pv for v in W[c]]
        for r in range(n):
            if r != c and W[r][c] != 0:
                f = W[r][c]
                W[r] = [W[r][j] - f * W[c][j] for j in range(2 * n)]
    return det, [row[n:] for row in W]


def _schur(A, B, D):
    d, Ai = _det_inv(A)
    if Ai is None:
        return d, None, None
    X = _mul(Ai, B)
    C = _mul(_tr(B), X)
    m = len(D)
    S = [[D[i][j] - C[i][j] for j in range(m)] for i in range(m)]
    return d, X, S


def _is_sq(f):
    if f <= 0:
        return False
    a = f.numerator
    b = f.denominator
    return isqrt(a) * isqrt(a) == a and isqrt(b) * isqrt(b) == b


def _sqrt(f):
    return Fraction(isqrt(f.numerator), isqrt(f.denominator))


def _load(case):
    A = case.get('A')
    B = case.get('B')
    D = case.get('D')
    if not (_ok_mat(A) and _ok_mat(B) and _ok_mat(D)):
        return None
    k = len(A)
    m = len(D)
    if len(A[0]) != k or len(D[0]) != m or len(B) != k or len(B[0]) != m:
        return None
    A = [[Fraction(v) for v in r] for r in A]
    B = [[Fraction(v) for v in r] for r in B]
    D = [[Fraction(v) for v in r] for r in D]
    if _tr(A) != A or _tr(D) != D:
        return None
    return A, B, D


def _shear(X, k, m):
    return _join(_ident(k), _neg(X), _zeros(m, k), _ident(m))


def _pred_schur_q(A, B, D):
    k = len(A)
    m = len(D)
    d, X, S = _schur(A, B, D)
    if X is None:
        return False
    M = _blocks(A, B, D)
    P = _shear(X, k, m)
    if _congr(P, M) != _blocks(A, _zeros(k, m), S):
        return None
    if _det_inv(P)[0] != 1:
        return None
    if _det_inv(M)[0] != d * _det_inv(S)[0]:
        return None
    adjB = _scal(d, X)
    Pint = _join(_scal(d, _ident(k)), _neg(adjB), _zeros(m, k), _scal(d, _ident(m)))
    C = _mul(_tr(B), adjB)
    low = [[d * d * D[i][j] - d * C[i][j] for j in range(m)] for i in range(m)]
    tint = _blocks(_scal(d * d, A), _zeros(k, m), low)
    if not (_is_intmat(Pint) and _is_intmat(tint)):
        return None
    if _congr(Pint, M) != tint:
        return None
    if _det_inv(Pint)[0] != d ** (k + m):
        return None
    return True


def _pred_schur_z(A, B, D, case):
    k = len(A)
    m = len(D)
    d, X, S = _schur(A, B, D)
    if X is None:
        return False
    xi = _is_intmat(X)
    si = _is_intmat(S)
    want = case.get('expect_s_integral')
    if isinstance(want, bool) and want != si:
        return None
    if xi:
        P = _shear(X, k, m)
        M = _blocks(A, B, D)
        if not si or not _is_intmat(P) or _det_inv(P)[0] != 1:
            return None
        if _congr(P, M) != _blocks(A, _zeros(k, m), S):
            return None
    return xi


def _pred_block_q(A, B, D):
    k = len(A)
    if len(D) != 1:
        return None
    d, X, S = _schur(A, B, D)
    if X is None:
        return None
    s = S[0][0]
    dd = D[0][0]
    M = _blocks(A, B, D)
    c = None
    if s == 0 and dd == 0:
        c = Fraction(1)
    elif s != 0 and dd != 0 and _is_sq(s * dd):
        c = _sqrt(s * dd) / s
    if c is not None:
        Q = _join(_ident(k), _scal(c, _neg(X)), _zeros(1, k), [[c]])
        if c == 0 or _congr(Q, M) != _blocks(A, _zeros(k, 1), D):
            return None
        return True
    detM = _det_inv(M)[0]
    if s != 0 and dd != 0:
        if _is_sq(detM / (d * dd)):
            return None
    elif (detM == 0) == (d * dd == 0):
        return None
    return False


def _mul2(X, Y):
    return [[sum(X[i][s] * Y[s][j] for s in range(len(Y))) % 2 for j in range(len(Y[0]))] for i in range(len(X))]


def _gf2_inv(A2):
    n = len(A2)
    W = [list(A2[i]) + [1 if i == j else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        piv = None
        for r in range(c, n):
            if W[r][c] % 2 == 1:
                piv = r
                break
        if piv is None:
            return None
        W[c], W[piv] = W[piv], W[c]
        for r in range(n):
            if r != c and W[r][c] % 2 == 1:
                W[r] = [(W[r][j] + W[c][j]) % 2 for j in range(2 * n)]
    return [row[n:] for row in W]


def _pred_gf2(A, B, D):
    k = len(A)
    m = len(D)
    d, X, S = _schur(A, B, D)
    A2 = [[v.numerator % 2 for v in r] for r in A]
    inv2 = _gf2_inv(A2)
    if d.numerator % 2 == 0:
        if inv2 is not None:
            return None
        return False
    if inv2 is None or X is None:
        return None
    if any(v.denominator % 2 == 0 for r in X + S for v in r):
        return None
    B2 = [[v.numerator % 2 for v in r] for r in B]
    D2 = [[v.numerator % 2 for v in r] for r in D]
    T = _mul2(_mul2(_tr(B2), inv2), B2)
    F = [[(D2[i][j] + T[i][j]) % 2 for j in range(m)] for i in range(m)]
    S2 = [[v.numerator % 2 for v in r] for r in S]
    if S2 != F:
        return None
    M = _blocks(A, B, D)
    if all(M[i][i].numerator % 2 == 0 for i in range(k + m)):
        if any(S[i][i].numerator % 2 != 0 for i in range(m)):
            return None
    return True


def _step(st, W, H):
    x, y, dx, dy = st
    nx = x + dx
    ny = y + dy
    if nx == 0 or nx == W:
        dx = -dx
    if ny == 0 or ny == H:
        dy = -dy
    return (nx, ny, dx, dy)


def _mirror_curves(p, q):
    W = 2 * p
    H = 2 * q
    states = []
    for x in range(W + 1):
        for y in range(H + 1):
            if (x + y) % 2 == 1:
                for dx in (1, -1):
                    for dy in (1, -1):
                        if 0 <= x + dx <= W and 0 <= y + dy <= H:
                            states.append((x, y, dx, dy))
    seen = set()
    cycles = 0
    limit = len(states) + 1
    for st in states:
        if st in seen:
            continue
        cur = st
        steps = 0
        while True:
            seen.add(cur)
            cur = _step(cur, W, H)
            steps += 1
            if cur == st:
                break
            if cur in seen or steps > limit:
                return None
        cycles += 1
    if cycles % 2 != 0:
        return None
    return cycles // 2


def _euclid(p, q):
    U = [[1, 0], [0, 1]]
    a, b = p, q
    while b != 0:
        t = a // b
        U = [[U[1][0], U[1][1]], [U[0][0] - t * U[1][0], U[0][1] - t * U[1][1]]]
        a, b = b, a - t * b
    return a, U


def _pred_mirror(case):
    p = case.get('p')
    q = case.get('q')
    if not (_isint(p) and _isint(q)):
        return None
    if p < 1 or q < 1 or p > 40 or q > 40:
        return None
    g = gcd(p, q)
    cnt = _mirror_curves(p, q)
    if cnt is None or cnt != g:
        return None
    a, U = _euclid(p, q)
    if a != g:
        return None
    if U[0][0] * p + U[0][1] * q != g or U[1][0] * p + U[1][1] * q != 0:
        return None
    if U[0][0] * U[1][1] - U[0][1] * U[1][0] not in (1, -1):
        return None
    claim = case.get('claim')
    if claim == 'curves':
        pc = case.get('claimed_curves')
        if not _isint(pc):
            return None
        return cnt == pc
    if claim == 'single_shear':
        return (cnt == 1) == (q % p == 0)
    return None


def check_case(case):
    try:
        if not isinstance(case, dict):
            return False
        exp = case.get('expected')
        if not isinstance(exp, bool):
            return False
        kind = case.get('kind')
        if kind == 'mirror':
            pred = _pred_mirror(case)
        else:
            L = _load(case)
            if L is None:
                return False
            A, B, D = L
            if kind == 'schur_q':
                pred = _pred_schur_q(A, B, D)
            elif kind == 'schur_z':
                pred = _pred_schur_z(A, B, D, case)
            elif kind == 'block_q':
                pred = _pred_block_q(A, B, D)
            elif kind == 'gf2_fold':
                pred = _pred_gf2(A, B, D)
            else:
                return False
        if not isinstance(pred, bool):
            return False
        return pred == exp
    except Exception:
        return False

from fractions import Fraction
from math import gcd, isqrt

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def mat_t(X):
    return [list(r) for r in zip(*X)]

def mat_mul(X, Y):
    k = len(Y)
    return [[sum(X[i][t] * Y[t][j] for t in range(k)) for j in range(len(Y[0]))] for i in range(len(X))]

def mat_sub(X, Y):
    return [[X[i][j] - Y[i][j] for j in range(len(X[0]))] for i in range(len(X))]

def mat_eq(X, Y):
    if len(X) != len(Y):
        return False
    for i in range(len(X)):
        if len(X[i]) != len(Y[i]):
            return False
        for j in range(len(X[i])):
            if X[i][j] != Y[i][j]:
                return False
    return True

def frac_mat(M):
    return [[Fraction(M[i][j]) for j in range(len(M[0]))] for i in range(len(M))]

def det_frac(M):
    n = len(M)
    if n == 0:
        return Fraction(1)
    F = frac_mat(M)
    det = Fraction(1)
    for c in range(n):
        p = None
        for r in range(c, n):
            if F[r][c] != 0:
                p = r
                break
        if p is None:
            return Fraction(0)
        if p != c:
            F[c], F[p] = F[p], F[c]
            det = -det
        det = det * F[c][c]
        inv = Fraction(1) / F[c][c]
        for r in range(c + 1, n):
            f = F[r][c] * inv
            if f != 0:
                for j in range(c, n):
                    F[r][j] = F[r][j] - f * F[c][j]
    return det

def minor(M, i, j):
    return [[M[r][c] for c in range(len(M[0])) if c != j] for r in range(len(M)) if r != i]

def adj_int(A):
    n = len(A)
    if n == 1:
        return [[1]]
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            v = det_frac(minor(A, i, j))
            if v.denominator != 1:
                return None
            cof = v.numerator
            if (i + j) % 2 == 1:
                cof = -cof
            C[j][i] = cof
    return C

def inv_frac(A):
    n = len(A)
    F = frac_mat(A)
    I = [[Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    for c in range(n):
        p = None
        for r in range(c, n):
            if F[r][c] != 0:
                p = r
                break
        if p is None:
            return None
        if p != c:
            F[c], F[p] = F[p], F[c]
            I[c], I[p] = I[p], I[c]
        piv = F[c][c]
        for j in range(n):
            F[c][j] = F[c][j] / piv
            I[c][j] = I[c][j] / piv
        for r in range(n):
            if r != c and F[r][c] != 0:
                f = F[r][c]
                for j in range(n):
                    F[r][j] = F[r][j] - f * F[c][j]
                    I[r][j] = I[r][j] - f * I[c][j]
    return I

def block4(A, B, D):
    k = len(A)
    m = len(D)
    n = k + m
    M = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(k):
        for j in range(k):
            M[i][j] = Fraction(A[i][j])
        for j in range(m):
            M[i][k + j] = Fraction(B[i][j])
    for i in range(m):
        for j in range(k):
            M[k + i][j] = Fraction(B[j][i])
        for j in range(m):
            M[k + i][k + j] = Fraction(D[i][j])
    return M

def block_diag(X, Y):
    k = len(X)
    m = len(Y)
    n = k + m
    R = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(k):
        for j in range(k):
            R[i][j] = Fraction(X[i][j])
    for i in range(m):
        for j in range(m):
            R[k + i][k + j] = Fraction(Y[i][j])
    return R

def shear_P(X, k, m):
    n = k + m
    P = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        P[i][i] = Fraction(1)
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -X[i][j]
    return P

def diag_congruence(M):
    F = frac_mat(M)
    size = len(F)
    out = []
    while size > 0:
        piv = None
        for r in range(size):
            if F[r][r] != 0:
                piv = r
                break
        if piv is None:
            found = False
            for r in range(size):
                for c in range(r + 1, size):
                    if F[r][c] != 0:
                        for j in range(size):
                            F[r][j] = F[r][j] + F[c][j]
                        for j in range(size):
                            F[j][r] = F[j][r] + F[j][c]
                        piv = r
                        found = True
                        break
                if found:
                    break
            if not found:
                for r in range(size):
                    out.append(Fraction(0))
                break
        if piv != 0:
            F[0], F[piv] = F[piv], F[0]
            for r in range(size):
                F[r][0], F[r][piv] = F[r][piv], F[r][0]
        out.append(F[0][0])
        inv = Fraction(1) / F[0][0]
        G = [[Fraction(0) for _ in range(size - 1)] for _ in range(size - 1)]
        for r in range(1, size):
            f = F[r][0] * inv
            for c in range(1, size):
                G[r - 1][c - 1] = F[r][c] - f * F[0][c]
        F = G
        size = size - 1
    return out

def inertia(M):
    ds = diag_congruence(M)
    pos = 0
    neg = 0
    for v in ds:
        if v > 0:
            pos = pos + 1
        elif v < 0:
            neg = neg + 1
    return (pos, neg)

def squarefree_part(n):
    s = 1
    if n < 0:
        s = -1
        n = -n
    res = 1
    p = 2
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n = n // p
                e = e + 1
            if e % 2 == 1:
                res = res * p
        p = p + (1 if p == 2 else 2)
    if n > 1:
        res = res * n
    return s * res

def is_square_rat(q):
    if q == 0:
        return True
    if q < 0:
        return False
    n = q.numerator * q.denominator
    r = isqrt(n)
    return r * r == n

def primes_of(x):
    ps = set()
    for n0 in (abs(x.numerator), x.denominator):
        n = n0
        p = 2
        while p * p <= n:
            if n % p == 0:
                ps.add(p)
                while n % p == 0:
                    n = n // p
            p = p + (1 if p == 2 else 2)
        if n > 1:
            ps.add(n)
    return ps

def inv_mod(a, m):
    a = a % m
    if gcd(a, m) != 1:
        return None
    old_r, r = a, m
    old_s, s = 1, 0
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
    return old_s % m

def val_unit(x, p):
    num = x.numerator
    den = x.denominator
    v = 0
    while num % p == 0:
        num = num // p
        v = v + 1
    while den % p == 0:
        den = den // p
        v = v - 1
    return (v, Fraction(num, den))

def legendre(u, p):
    iv = inv_mod(u.denominator % p, p)
    if iv is None:
        return 0
    a = (u.numerator * iv) % p
    if a == 0:
        return 0
    r = pow(a, (p - 1) // 2, p)
    return 1 if r == 1 else -1

def hilbert_odd(a, b, p):
    va, ua = val_unit(a, p)
    vb, ub = val_unit(b, p)
    e = (va * vb * ((p - 1) // 2)) % 2
    s = -1 if e == 1 else 1
    if vb % 2 == 1:
        s = s * legendre(ua, p)
    if va % 2 == 1:
        s = s * legendre(ub, p)
    return s

def hilbert_two(a, b):
    va, ua = val_unit(a, 2)
    vb, ub = val_unit(b, 2)
    iu = inv_mod(ua.denominator % 8, 8)
    iv = inv_mod(ub.denominator % 8, 8)
    if iu is None or iv is None:
        return 1
    u8 = (ua.numerator * iu) % 8
    v8 = (ub.numerator * iv) % 8
    eu = 1 if u8 % 4 == 3 else 0
    ev = 1 if v8 % 4 == 3 else 0
    wu = 1 if (u8 == 3 or u8 == 5) else 0
    wv = 1 if (v8 == 3 or v8 == 5) else 0
    e = (eu * ev + va * wv + vb * wu) % 2
    return -1 if e == 1 else 1

def hasse_at(ds, p):
    nz = [v for v in ds if v != 0]
    s = 1
    for i in range(len(nz)):
        for j in range(i + 1, len(nz)):
            if p == 2:
                s = s * hilbert_two(nz[i], nz[j])
            else:
                s = s * hilbert_odd(nz[i], nz[j], p)
    return s

def q_invariants(M):
    ds = diag_congruence(M)
    pos = 0
    neg = 0
    prod = Fraction(1)
    ps = set([2])
    for v in ds:
        if v > 0:
            pos = pos + 1
        elif v < 0:
            neg = neg + 1
        if v != 0:
            prod = prod * v
            ps = ps | primes_of(v)
    rank = pos + neg
    if rank == 0:
        dc = 0
    else:
        dc = squarefree_part(prod.numerator * prod.denominator)
    hs = {}
    for p in sorted(ps):
        hs[p] = hasse_at(ds, p)
    return (rank, pos, neg, dc, hs)

def q_congruent(M1, M2):
    a = q_invariants(M1)
    b = q_invariants(M2)
    if a[0] != b[0] or a[1] != b[1] or a[2] != b[2] or a[3] != b[3]:
        return False
    ps = set(a[4]) | set(b[4])
    for p in ps:
        if a[4].get(p, 1) != b[4].get(p, 1):
            return False
    return True

def all_integral(F):
    for row in F:
        for v in row:
            if v.denominator != 1:
                return False
    return True

def all_odd_den(F):
    for row in F:
        for v in row:
            if v.denominator % 2 == 0:
                return False
    return True

def schur_data(case):
    A = case['A']
    B = case['B']
    D = case['D']
    k = len(A)
    m = len(D)
    if k == 0 or m == 0 or len(B) != k:
        return None
    for row in A:
        if len(row) != k:
            return None
        for v in row:
            if not is_int(v):
                return None
    for row in B:
        if len(row) != m:
            return None
        for v in row:
            if not is_int(v):
                return None
    for row in D:
        if len(row) != m:
            return None
        for v in row:
            if not is_int(v):
                return None
    for i in range(k):
        for j in range(k):
            if A[i][j] != A[j][i]:
                return None
    for i in range(m):
        for j in range(m):
            if D[i][j] != D[j][i]:
                return None
    d = det_frac(A)
    if d == 0 or d.denominator != 1:
        return None
    adj = adj_int(A)
    if adj is None:
        return None
    Ai = inv_frac(A)
    if Ai is None:
        return None
    X = mat_mul(Ai, frac_mat(B))
    S = mat_sub(frac_mat(D), mat_mul(mat_t(frac_mat(B)), X))
    return (A, B, D, k, m, d.numerator, adj, X, S)

def canonical_ok(A, B, D, X, S):
    k = len(A)
    m = len(D)
    M = block4(A, B, D)
    P = shear_P(X, k, m)
    lhs = mat_mul(mat_t(P), mat_mul(M, P))
    return mat_eq(lhs, block_diag(A, S))

def pred_schur_q(case):
    sd = schur_data(case)
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    if not canonical_ok(A, B, D, X, S):
        return None
    M = block4(A, B, D)
    if det_frac(M) != Fraction(dint) * det_frac(S):
        return None
    im = inertia(M)
    ia = inertia(A)
    isv = inertia(S)
    if im != (ia[0] + isv[0], ia[1] + isv[1]):
        return None
    return True

def pred_schur_z(case):
    sd = schur_data(case)
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    adjB = mat_mul(adj, B)
    for row in adjB:
        for v in row:
            if v % dint != 0:
                return False
    if not all_integral(X):
        return None
    if not all_integral(S):
        return None
    if not canonical_ok(A, B, D, X, S):
        return None
    return True

def pred_scaled_z(case):
    sd = schur_data(case)
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    adjB = mat_mul(adj, B)
    n = k + m
    P = [[0] * n for _ in range(n)]
    for i in range(k):
        P[i][i] = dint
    for i in range(m):
        P[k + i][k + i] = dint
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -adjB[i][j]
    M = block4(A, B, D)
    Pi = frac_mat(P)
    lhs = mat_mul(mat_t(Pi), mat_mul(M, Pi))
    d2 = dint * dint
    A2 = [[d2 * A[i][j] for j in range(k)] for i in range(k)]
    BTadjB = mat_mul(mat_t(B), adjB)
    D2 = [[d2 * D[i][j] - dint * BTadjB[i][j] for j in range(m)] for i in range(m)]
    if not mat_eq(lhs, block_diag(A2, D2)):
        return None
    if not all_integral(lhs):
        return None
    if det_frac(P) != Fraction(dint) ** n:
        return None
    for i in range(m):
        for j in range(m):
            if Fraction(D2[i][j]) != Fraction(d2) * S[i][j]:
                return None
    return True

def pred_block_q(case):
    sd = schur_data(case)
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    if not canonical_ok(A, B, D, X, S):
        return None
    res = q_congruent(D, S)
    M = block4(A, B, D)
    AD = block_diag(A, D)
    if q_congruent(M, AD) != res:
        return None
    if m == 1:
        dv = D[0][0]
        sv = S[0][0]
        if dv == 0 and sv == 0:
            crit = True
        elif dv == 0 or sv == 0:
            crit = False
        else:
            crit = is_square_rat(Fraction(dv) * sv)
        if crit != res:
            return None
    return res

def pred_hasse_gap(case):
    sd = schur_data(case)
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    if not all_integral(X):
        return False
    if not canonical_ok(A, B, D, X, S):
        return None
    iD = q_invariants(D)
    iS = q_invariants(S)
    if iD[0] != m or iS[0] != m:
        return False
    if iD[1] != iS[1] or iD[2] != iS[2]:
        return False
    if iD[3] != iS[3]:
        return False
    if q_congruent(D, S):
        return False
    M = block4(A, B, D)
    ratio = det_frac(M) / (Fraction(dint) * det_frac(D))
    if not is_square_rat(ratio):
        return False
    if inertia(M) != inertia(block_diag(A, D)):
        return False
    ps = set(iD[4]) | set(iS[4])
    found = False
    for p in ps:
        if iD[4].get(p, 1) != iS[4].get(p, 1):
            found = True
    if not found:
        return None
    return True

def gf2_inv(M):
    n = len(M)
    F = [[M[i][j] % 2 for j in range(n)] for i in range(n)]
    I = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        p = None
        for r in range(c, n):
            if F[r][c] == 1:
                p = r
                break
        if p is None:
            return None
        if p != c:
            F[c], F[p] = F[p], F[c]
            I[c], I[p] = I[p], I[c]
        for r in range(n):
            if r != c and F[r][c] == 1:
                for j in range(n):
                    F[r][j] ^= F[c][j]
                    I[r][j] ^= I[c][j]
    return I

def pred_gf2_regime(case):
    sd = schur_data(case['odd'])
    if sd is None:
        return False
    A, B, D, k, m, dint, adj, X, S = sd
    if dint % 2 == 0:
        return False
    if not all_odd_den(X) or not all_odd_den(S):
        return None
    A2 = gf2_inv(A)
    if A2 is None:
        return None
    B2 = [[B[i][j] % 2 for j in range(m)] for i in range(k)]
    D2 = [[D[i][j] % 2 for j in range(m)] for i in range(m)]
    T = mat_mul(mat_t(B2), mat_mul(A2, B2))
    S2 = [[(D2[i][j] + T[i][j]) % 2 for j in range(m)] for i in range(m)]
    Sm = [[(S[i][j].numerator * inv_mod(S[i][j].denominator, 2)) % 2 for j in range(m)] for i in range(m)]
    if not mat_eq(S2, Sm):
        return None
    sde = schur_data(case['even'])
    if sde is None:
        return False
    if sde[5] % 2 != 0:
        return False
    if gf2_inv(sde[0]) is not None:
        return None
    M1 = case['pair'][0]
    M2 = case['pair'][1]
    c1 = {'A': [[M1[0][0]]], 'B': [[M1[0][1]]], 'D': [[M1[1][1]]]}
    c2 = {'A': [[M2[0][0]]], 'B': [[M2[0][1]]], 'D': [[M2[1][1]]]}
    s1 = schur_data(c1)
    s2 = schur_data(c2)
    if s1 is None or s2 is None:
        return False
    if s1[5] % 2 == 0 or s2[5] % 2 == 0:
        return False
    S1 = s1[8]
    Sb = s2[8]
    f1 = [[S1[i][j].numerator % 2 for j in range(len(S1[0]))] for i in range(len(S1))]
    f2 = [[Sb[i][j].numerator % 2 for j in range(len(Sb[0]))] for i in range(len(Sb))]
    if not mat_eq(f1, f2):
        return False
    def1 = s1[5] * S1[0][0]
    def2 = s2[5] * Sb[0][0]
    if def1.denominator != 1 or def2.denominator != 1:
        return None
    if def1.numerator == def2.numerator:
        return False
    for i in range(2):
        for j in range(2):
            if M1[i][j] % 2 != M2[i][j] % 2:
                return False
    return True

def mirror_components(p, q):
    seen = set()
    count = 0
    for i in range(p):
        for j in range(q):
            if (i, j) in seen:
                continue
            count = count + 1
            x, y = i, j
            while True:
                seen.add((x, y))
                x = (x + 1) % p
                y = (y + 1) % q
                if (x, y) == (i, j):
                    break
    return count

def euclid_shears(p, q):
    a, b = p, q
    steps = 0
    while b != 0:
        if a >= b:
            k = a // b
            a = a - k * b
            steps = steps + k
        else:
            a, b = b, a
    return (a, steps)

def pred_mirror_regime(case):
    for g in case['grids']:
        p = g[0]
        q = g[1]
        if not is_int(p) or not is_int(q) or p <= 0 or q <= 0:
            return False
        cnt = mirror_components(p, q)
        if cnt != gcd(p, q):
            return None
        if (cnt == 1) != (gcd(p, q) == 1):
            return None
    p, q = 2, 3
    if gcd(p, q) != 1:
        return None
    if q % p == 0:
        return False
    a, steps = euclid_shears(p, q)
    if a != 1 or steps <= 1:
        return None
    M1 = [[1, 0], [0, 1]]
    M2 = [[1, 0], [0, -1]]
    for i in range(2):
        for j in range(2):
            if M1[i][j] % 2 != M2[i][j] % 2:
                return None
    if inertia(M1) == inertia(M2):
        return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get('expected')
    if not isinstance(exp, bool):
        return False
    pr = case.get('pred')
    if pr == 'schur_q':
        r = pred_schur_q(case)
    elif pr == 'schur_z':
        r = pred_schur_z(case)
    elif pr == 'scaled_z':
        r = pred_scaled_z(case)
    elif pr == 'block_q':
        r = pred_block_q(case)
    elif pr == 'hasse_gap':
        r = pred_hasse_gap(case)
    elif pr == 'gf2_regime':
        r = pred_gf2_regime(case)
    elif pr == 'mirror_regime':
        r = pred_mirror_regime(case)
    else:
        return False
    if not isinstance(r, bool):
        return False
    return r == exp

from fractions import Fraction
from math import gcd, isqrt

FLAG_KEYS = ('schur_q', 'schur_z_canonical', 'drop_shear_q', 'drop_q',
             'drop_z_canonical', 'scaled_z', 'gf2_fold')

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def lcm_int(a, b):
    if a <= 0 or b <= 0:
        return 0
    return (a // gcd(a, b)) * b

def zeros(r, c):
    return [[Fraction(0) for _ in range(c)] for _ in range(r)]

def to_frac(M):
    return [[Fraction(x) for x in row] for row in M]

def mat_mul(P, Q):
    n = len(P)
    t = len(Q)
    m = len(Q[0])
    R = zeros(n, m)
    for i in range(n):
        for k in range(t):
            pik = P[i][k]
            if pik != 0:
                Qk = Q[k]
                Ri = R[i]
                for j in range(m):
                    Ri[j] = Ri[j] + pik * Qk[j]
    return R

def mat_add(P, Q):
    return [[P[i][j] + Q[i][j] for j in range(len(P[0]))] for i in range(len(P))]

def mat_sub(P, Q):
    return [[P[i][j] - Q[i][j] for j in range(len(P[0]))] for i in range(len(P))]

def transpose(P):
    return [[P[i][j] for i in range(len(P))] for j in range(len(P[0]))]

def det_frac(M):
    n = len(M)
    W = [list(row) for row in M]
    d = Fraction(1)
    for i in range(n):
        piv = -1
        for r in range(i, n):
            if W[r][i] != 0:
                piv = r
                break
        if piv < 0:
            return Fraction(0)
        if piv != i:
            W[i], W[piv] = W[piv], W[i]
            d = -d
        pv = W[i][i]
        d = d * pv
        for r in range(i + 1, n):
            if W[r][i] != 0:
                f = W[r][i] / pv
                Wr = W[r]
                Wi = W[i]
                for c in range(i, n):
                    Wr[c] = Wr[c] - f * Wi[c]
    return d

def det_int(MF):
    d = det_frac(MF)
    if d.denominator != 1:
        return None
    return d.numerator

def remove_rc(M, ri, ci):
    return [[M[i][j] for j in range(len(M[0])) if j != ci] for i in range(len(M)) if i != ri]

def adj_frac(M):
    n = len(M)
    if n == 1:
        return [[Fraction(1)]]
    out = zeros(n, n)
    for i in range(n):
        for j in range(n):
            sg = -1 if (i + j) % 2 else 1
            out[i][j] = Fraction(sg) * det_frac(remove_rc(M, j, i))
    return out

def inv_frac(M):
    n = len(M)
    d = det_frac(M)
    ad = adj_frac(M)
    return [[ad[i][j] / d for j in range(n)] for i in range(n)]

def is_square_frac(f):
    if f < 0:
        return False
    n = f.numerator
    q = f.denominator
    rn = isqrt(n)
    rq = isqrt(q)
    return rn * rn == n and rq * rq == q

def frac_mod2(f):
    if f.denominator % 2 == 0:
        return None
    return f.numerator % 2

def mat_mod2(MF):
    out = []
    for row in MF:
        rr = []
        for x in row:
            v = frac_mod2(x)
            if v is None:
                return None
            rr.append(v)
        out.append(rr)
    return out

def build_M(A, B, D):
    k = len(A)
    m = len(D)
    M = []
    for i in range(k):
        M.append([Fraction(A[i][j]) for j in range(k)] + [Fraction(B[i][j]) for j in range(m)])
    for i in range(m):
        M.append([Fraction(B[t][i]) for t in range(k)] + [Fraction(D[i][j]) for j in range(m)])
    return M

def shear_P(X, k, m):
    P = []
    for i in range(k):
        P.append([Fraction(1) if i == j else Fraction(0) for j in range(k)] + [-X[i][j] for j in range(m)])
    for i in range(m):
        P.append([Fraction(0) for _ in range(k)] + [Fraction(1) if i == j else Fraction(0) for j in range(m)])
    return P

def analyze(A, B, D):
    if not (isinstance(A, list) and isinstance(B, list) and isinstance(D, list)):
        return None
    k = len(A)
    m = len(D)
    if k == 0 or m == 0 or len(B) != k:
        return None
    for i in range(k):
        row = A[i]
        if not isinstance(row, list) or len(row) != k:
            return None
        for x in row:
            if not is_int(x):
                return None
    for i in range(k):
        for j in range(k):
            if A[i][j] != A[j][i]:
                return None
    for t in range(k):
        row = B[t]
        if not isinstance(row, list) or len(row) != m:
            return None
        for x in row:
            if not is_int(x):
                return None
    for i in range(m):
        row = D[i]
        if not isinstance(row, list) or len(row) != m:
            return None
        for x in row:
            if not is_int(x):
                return None
    for i in range(m):
        for j in range(m):
            if D[i][j] != D[j][i]:
                return None
    AF = to_frac(A)
    BF = to_frac(B)
    DF = to_frac(D)
    res = {}
    for key in FLAG_KEYS:
        res[key] = False
    dA = det_int(AF)
    if dA is None or dA == 0:
        return res
    X = mat_mul(inv_frac(AF), BF)
    BtX = mat_mul(transpose(BF), X)
    S = mat_sub(DF, BtX)
    Mbig = build_M(A, B, D)
    P = shear_P(X, k, m)
    LHS = mat_mul(mat_mul(transpose(P), Mbig), P)
    ok = True
    for i in range(k + m):
        for j in range(k + m):
            if i < k and j < k:
                tgt = AF[i][j]
            elif i >= k and j >= k:
                tgt = S[i - k][j - k]
            else:
                tgt = Fraction(0)
            if LHS[i][j] != tgt:
                ok = False
    res['schur_q'] = ok
    xint = True
    for row in X:
        for x in row:
            if x.denominator != 1:
                xint = False
    res['schur_z_canonical'] = xint
    zcross = True
    for row in BtX:
        for x in row:
            if x != 0:
                zcross = False
    res['drop_shear_q'] = zcross
    dq = False
    if m == 1:
        s = S[0][0]
        dv = DF[0][0]
        if s == 0 and dv == 0:
            dq = True
        elif s != 0 and dv != 0:
            dq = is_square_frac(s * dv)
            dM = det_int(Mbig)
            if dM is None:
                dq = False
            else:
                w = is_square_frac(Fraction(dM, dA * D[0][0]))
                if w != dq:
                    dq = False
    res['drop_q'] = dq
    res['drop_z_canonical'] = zcross and xint
    adjA = adj_frac(AF)
    W = mat_mul(adjA, BF)
    BtWB = mat_mul(mat_mul(transpose(BF), adjA), BF)
    wint = True
    for row in W:
        for x in row:
            if x.denominator != 1:
                wint = False
    for row in BtWB:
        for x in row:
            if x.denominator != 1:
                wint = False
    scaled = wint
    if scaled:
        Pint = []
        for i in range(k):
            Pint.append([Fraction(dA) if i == j else Fraction(0) for j in range(k)] + [-W[i][j] for j in range(m)])
        for i in range(m):
            Pint.append([Fraction(0) for _ in range(k)] + [Fraction(dA) if i == j else Fraction(0) for j in range(m)])
        LHS2 = mat_mul(mat_mul(transpose(Pint), Mbig), Pint)
        d2 = Fraction(dA * dA)
        for i in range(k + m):
            for j in range(k + m):
                if i < k and j < k:
                    tgt = d2 * AF[i][j]
                elif i >= k and j >= k:
                    tgt = d2 * DF[i - k][j - k] - Fraction(dA) * BtWB[i - k][j - k]
                else:
                    tgt = Fraction(0)
                if LHS2[i][j] != tgt:
                    scaled = False
        pdet = 1
        for _ in range(k + m):
            pdet = pdet * dA
        if det_frac(Pint) != Fraction(pdet):
            scaled = False
    res['scaled_z'] = scaled
    if dA % 2 == 1:
        S2 = mat_mod2(S)
        G2 = mat_mod2(mat_add(DF, BtWB))
        if S2 is None or G2 is None:
            res['gf2_fold'] = False
        else:
            res['gf2_fold'] = (S2 == G2)
    return res

def mirror_curves(p, q):
    P = 2 * p
    Q = 2 * q
    per = lcm_int(P, Q)
    reps = set()
    for i in range(p):
        for j in range(q):
            bx = 2 * i
            by = 2 * j
            cx = bx
            cy = by
            for _ in range(per):
                cx = (cx + 1) % P
                cy = (cy + 1) % Q
                if cx < bx or (cx == bx and cy < by):
                    bx = cx
                    by = cy
            reps.add((bx, by))
    return len(reps)

def match_flags(pred, expect):
    if not isinstance(expect, dict) or len(expect) == 0:
        return False
    for key in expect:
        if key not in pred:
            return False
        ev = expect[key]
        if not isinstance(ev, bool):
            return False
        pv = pred[key]
        if not isinstance(pv, bool):
            return False
        if ev != pv:
            return False
    return True

def check_case(case):
    if not isinstance(case, dict):
        return False
    if 'p' in case and 'q' in case:
        p = case['p']
        q = case['q']
        if not is_int(p) or not is_int(q):
            return False
        if p <= 0 or q <= 0:
            return False
        if 'expect' not in case:
            return False
        cnt = mirror_curves(p, q)
        pred = {'eulerian_single_curve': cnt == 1,
                'single_shear_reducible': q % p == 0}
        return match_flags(pred, case['expect'])
    for req in ('A', 'B', 'D', 'expect'):
        if req not in case:
            return False
    res = analyze(case['A'], case['B'], case['D'])
    if res is None:
        return False
    return match_flags(res, case['expect'])

from fractions import Fraction
from math import gcd, isqrt


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _as_fraction(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, int):
        return Fraction(x)
    if isinstance(x, Fraction):
        return x
    return None


def _int_mat(rows):
    if not isinstance(rows, list):
        return None
    n = len(rows)
    if n == 0:
        return None
    out = []
    for row in rows:
        if not isinstance(row, list) or len(row) != n:
            return None
        r = []
        for x in row:
            v = _as_fraction(x)
            if v is None:
                return None
            r.append(v)
        out.append(r)
    return out


def _T(A):
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]


def _mul(A, B):
    n = len(A)
    k = len(B)
    m = len(B[0])
    out = []
    for i in range(n):
        row = []
        for j in range(m):
            s = Fraction(0)
            for t in range(k):
                s = s + A[i][t] * B[t][j]
            row.append(s)
        out.append(row)
    return out


def _det(A):
    n = len(A)
    W = [[Fraction(x) for x in row] for row in A]
    d = Fraction(1)
    for c in range(n):
        p = -1
        for r in range(c, n):
            if W[r][c] != 0:
                p = r
                break
        if p < 0:
            return Fraction(0)
        if p != c:
            W[c], W[p] = W[p], W[c]
            d = -d
        pv = W[c][c]
        d = d * pv
        for r in range(c + 1, n):
            f = W[r][c] / pv
            if f != 0:
                for j in range(c, n):
                    W[r][j] = W[r][j] - f * W[c][j]
    return d


def _inv(A):
    n = len(A)
    W = []
    for i in range(n):
        row = [Fraction(x) for x in A[i]]
        row = row + [Fraction(1) if j == i else Fraction(0) for j in range(n)]
        W.append(row)
    for c in range(n):
        p = -1
        for r in range(c, n):
            if W[r][c] != 0:
                p = r
                break
        if p < 0:
            return None
        if p != c:
            W[c], W[p] = W[p], W[c]
        pv = W[c][c]
        W[c] = [x / pv for x in W[c]]
        for r in range(n):
            if r != c and W[r][c] != 0:
                f = W[r][c]
                W[r] = [W[r][j] - f * W[c][j] for j in range(2 * n)]
    return [row[n:] for row in W]


def _blocks(M, k, m):
    A = [[M[i][j] for j in range(k)] for i in range(k)]
    B = [[M[i][k + j] for j in range(m)] for i in range(k)]
    D = [[M[k + i][k + j] for j in range(m)] for i in range(m)]
    return A, B, D


def _blockdiag(A, C):
    k = len(A)
    m = len(C)
    out = []
    for i in range(k):
        out.append([A[i][j] for j in range(k)] + [Fraction(0) for _ in range(m)])
    for i in range(m):
        out.append([Fraction(0) for _ in range(k)] + [C[i][j] for j in range(m)])
    return out


def _shear_P(k, m, X):
    P = []
    for i in range(k):
        row = [Fraction(1) if j == i else Fraction(0) for j in range(k)]
        row = row + [-X[i][j] for j in range(m)]
        P.append(row)
    for i in range(m):
        row = [Fraction(0) for _ in range(k)]
        row = row + [Fraction(1) if j == i else Fraction(0) for j in range(m)]
        P.append(row)
    return P


def _scaled_P(k, m, d, adjB):
    P = []
    for i in range(k):
        row = [d if j == i else Fraction(0) for j in range(k)]
        row = row + [-adjB[i][j] for j in range(m)]
        P.append(row)
    for i in range(m):
        row = [Fraction(0) for _ in range(k)]
        row = row + [d if j == i else Fraction(0) for j in range(m)]
        P.append(row)
    return P


def _eqm(X, Y):
    if len(X) != len(Y):
        return False
    for i in range(len(X)):
        if len(X[i]) != len(Y[i]):
            return False
        for j in range(len(X[i])):
            if X[i][j] != Y[i][j]:
                return False
    return True


def _integral(rows):
    for row in rows:
        for x in row:
            if x.denominator != 1:
                return False
    return True


def _to_ints(rows):
    out = []
    for row in rows:
        r = []
        for x in row:
            if x.denominator != 1:
                return None
            r.append(int(x))
        out.append(r)
    return out


def _zero(rows):
    for row in rows:
        for x in row:
            if x != 0:
                return False
    return True


def _iadd(t1, t2):
    return (t1[0] + t2[0], t1[1] + t2[1], t1[2] + t2[2])


def _inertia(mat):
    A = [[Fraction(x) for x in row] for row in mat]
    n = len(A)
    pos = 0
    neg = 0
    zer = 0
    c = 0
    while c < n:
        p = -1
        for r in range(c, n):
            if A[r][r] != 0:
                p = r
                break
        if p < 0:
            pair = None
            for r in range(c, n):
                for s in range(r + 1, n):
                    if A[r][s] != 0:
                        pair = (r, s)
                        break
                if pair is not None:
                    break
            if pair is None:
                zer = zer + n - c
                break
            r0 = pair[0]
            s0 = pair[1]
            for i in range(n):
                A[i][s0] = A[i][s0] + A[i][r0]
            for j in range(n):
                A[s0][j] = A[s0][j] + A[r0][j]
            continue
        if p != c:
            A[c], A[p] = A[p], A[c]
            for i in range(n):
                A[i][c], A[i][p] = A[i][p], A[i][c]
        pv = A[c][c]
        if pv > 0:
            pos = pos + 1
        else:
            neg = neg + 1
        for r in range(c + 1, n):
            if A[r][c] != 0:
                f = A[r][c] / pv
                for j in range(n):
                    A[r][j] = A[r][j] - f * A[c][j]
                for i in range(n):
                    A[i][r] = A[i][r] - f * A[i][c]
        c = c + 1
    return (pos, neg, zer)


def _square_in_Q(r):
    r = Fraction(r)
    if r < 0:
        return False
    if r == 0:
        return True
    num = r.numerator
    den = r.denominator
    a = isqrt(num)
    b = isqrt(den)
    return a * a == num and b * b == den


def _mod2_rows(rows):
    out = []
    for row in rows:
        r = []
        for x in row:
            f = _as_fraction(x)
            if f is None or f.denominator != 1:
                return None
            r.append(int(f) % 2)
        out.append(r)
    return out


def _add2(A, B):
    return [[(A[i][j] + B[i][j]) % 2 for j in range(len(A[0]))] for i in range(len(A))]


def _mul2(A, B):
    n = len(A)
    k = len(B)
    m = len(B[0])
    out = []
    for i in range(n):
        row = []
        for j in range(m):
            s = 0
            for t in range(k):
                s = s + A[i][t] * B[t][j]
            row.append(s % 2)
        out.append(row)
    return out


def _inv2(A):
    n = len(A)
    W = [list(A[i]) + [1 if j == i else 0 for j in range(n)] for i in range(n)]
    for c in range(n):
        p = -1
        for r in range(c, n):
            if W[r][c] == 1:
                p = r
                break
        if p < 0:
            return None
        if p != c:
            W[c], W[p] = W[p], W[c]
        for r in range(n):
            if r != c and W[r][c] == 1:
                W[r] = [(W[r][j] + W[c][j]) % 2 for j in range(2 * n)]
    return [row[n:] for row in W]


def _frac_mod2(x):
    if x.denominator % 2 == 0:
        return None
    return x.numerator % 2


def _schur_parts(M, k, m):
    A, B, D = _blocks(M, k, m)
    d = _det(A)
    if d == 0:
        return None
    Ainv = _inv(A)
    if Ainv is None:
        return None
    Bt = _T(B)
    X = _mul(Ainv, B)
    Y = _mul(_mul(Bt, Ainv), B)
    S = [[D[i][j] - Y[i][j] for j in range(m)] for i in range(m)]
    return {'A': A, 'B': B, 'D': D, 'Bt': Bt, 'X': X, 'Y': Y, 'S': S, 'Ainv': Ainv, 'd': d}


def _fold_image(M, k, m):
    parts = _schur_parts(M, k, m)
    if parts is None:
        return None
    d = parts['d']
    if int(d) % 2 == 0:
        return None
    S = parts['S']
    out = []
    for row in S:
        r = []
        for x in row:
            v = _frac_mod2(x)
            if v is None:
                return None
            r.append(v)
        out.append(r)
    return out


def _fold_commutes(M, k, m):
    parts = _schur_parts(M, k, m)
    if parts is None:
        return None
    d = parts['d']
    if int(d) % 2 == 0:
        return False
    S2 = _fold_image(M, k, m)
    A2 = _mod2_rows(parts['A'])
    B2 = _mod2_rows(parts['B'])
    D2 = _mod2_rows(parts['D'])
    if S2 is None or A2 is None or B2 is None or D2 is None:
        return None
    Ai2 = _inv2(A2)
    if Ai2 is None:
        return None
    pred = _add2(D2, _mul2(_mul2(_T(B2), Ai2), B2))
    return _eqm(S2, pred)


def _defect(M, k, m):
    parts = _schur_parts(M, k, m)
    if parts is None:
        return None
    D = parts['D']
    Y = parts['Y']
    d = parts['d']
    mm = len(D)
    return [[d * D[i][j] - d * Y[i][j] for j in range(mm)] for i in range(mm)]


def _analyse(M, k, m):
    parts = _schur_parts(M, k, m)
    if parts is None:
        return None
    A = parts['A']
    B = parts['B']
    D = parts['D']
    Bt = parts['Bt']
    X = parts['X']
    Y = parts['Y']
    S = parts['S']
    d = parts['d']
    adj = [[d * parts['Ainv'][i][j] for j in range(k)] for i in range(k)]
    adjB = _mul(adj, B)
    ints = _to_ints(adjB)
    if ints is None:
        return None
    di = int(d)
    div_ok = True
    for row in ints:
        for x in row:
            if x % di != 0:
                div_ok = False
    shear_int = _integral(X)
    s_int = _integral(S)
    if shear_int != div_ok:
        return None
    if shear_int and not s_int:
        return None
    P = _shear_P(k, m, X)
    cong_q = _eqm(_mul(_mul(_T(P), M), P), _blockdiag(A, S))
    detM = _det(M)
    det_mult = (detM == d * _det(S))
    inertia_add = (_inertia(M) == _iadd(_inertia(A), _inertia(S)))
    Pint = _scaled_P(k, m, d, adjB)
    lhs_s = _mul(_mul(_T(Pint), M), Pint)
    BTadjB = _mul(_mul(Bt, adj), B)
    d2 = d * d
    rhs_top = [[d2 * A[i][j] for j in range(k)] for i in range(k)]
    rhs_bot = [[d2 * D[i][j] - d * BTadjB[i][j] for j in range(m)] for i in range(m)]
    scaled = _eqm(lhs_s, _blockdiag(rhs_top, rhs_bot))
    det_Pint = (_det(Pint) == d ** (k + m))
    drop_ok = _zero(Y)
    if drop_ok != _zero(BTadjB):
        return None
    detD = _det(D)
    if detD == 0:
        det_class_ok = (detM == 0)
    else:
        det_class_ok = _square_in_Q(detM / (d * detD))
    inertia_block_ok = (_inertia(M) == _iadd(_inertia(A), _inertia(D)))
    obstructed = not (det_class_ok and inertia_block_ok)
    return {'cong_q': cong_q, 'det_mult': det_mult, 'inertia_add': inertia_add,
            'shear_int': shear_int, 'scaled': scaled, 'det_Pint': det_Pint,
            'drop_ok': drop_ok, 'det_class_ok': det_class_ok,
            'inertia_block_ok': inertia_block_ok, 'obstructed': obstructed}


def _orbit_components(p, q):
    if p <= 0 or q <= 0:
        return 0
    seen = set()
    seen.add((0, 0))
    a = 1 % p
    b = 1 % q
    length = 1
    while (a, b) != (0, 0):
        if (a, b) in seen:
            return 0
        seen.add((a, b))
        a = (a + 1) % p
        b = (b + 1) % q
        length = length + 1
    return (p * q) // length


def _predict(case):
    kind = case.get('kind')
    if kind == 'mirror_counts':
        grids = case.get('grids')
        counts = case.get('components')
        if not isinstance(grids, list) or not isinstance(counts, list):
            return None
        if len(grids) == 0 or len(grids) != len(counts):
            return None
        for i in range(len(grids)):
            g = grids[i]
            if not isinstance(g, list) or len(g) != 2:
                return None
            p = g[0]
            q = g[1]
            if not _is_int(p) or not _is_int(q) or p <= 0 or q <= 0:
                return None
            c = _orbit_components(p, q)
            if c != gcd(p, q) or c != counts[i]:
                return False
        return True
    if kind == 'schur_q' or kind == 'schur_z' or kind == 'scaled_z' or kind == 'block_layer':
        M = _int_mat(case.get('M'))
        k = case.get('k')
        m = case.get('m')
        if M is None or not _is_int(k) or not _is_int(m):
            return None
        if k < 1 or m < 1 or len(M) != k + m:
            return None
        info = _analyse(M, k, m)
        if info is None:
            return None
        if kind == 'schur_q':
            return bool(info['cong_q'] and info['det_mult'] and info['inertia_add'])
        if kind == 'schur_z':
            return bool(info['shear_int'])
        if kind == 'scaled_z':
            return bool(info['scaled'] and info['det_Pint'])
        if k != 1 or m != 1:
            return None
        return bool((not info['drop_ok']) and (not info['obstructed']) and info['det_class_ok'] and info['inertia_block_ok'])
    if kind == 'gf2_fold':
        subs = case.get('fold_cases')
        if not isinstance(subs, list) or len(subs) == 0:
            return None
        for sub in subs:
            if not isinstance(sub, dict):
                return None
            M = _int_mat(sub.get('M'))
            k = sub.get('k')
            m = sub.get('m')
            want = sub.get('expect_commutes')
            if M is None or not _is_int(k) or not _is_int(m) or not isinstance(want, bool):
                return None
            if len(M) != k + m:
                return None
            got = _fold_commutes(M, k, m)
            if got is None:
                return None
            if got != want:
                return False
        return True
    if kind == 'gf2_lift_split':
        M1 = _int_mat(case.get('M1'))
        M2 = _int_mat(case.get('M2'))
        k = case.get('k')
        m = case.get('m')
        if M1 is None or M2 is None or not _is_int(k) or not _is_int(m):
            return None
        if len(M1) != k + m or len(M2) != k + m:
            return None
        i1 = _mod2_rows(M1)
        i2 = _mod2_rows(M2)
        f1 = _fold_image(M1, k, m)
        f2 = _fold_image(M2, k, m)
        d1 = _defect(M1, k, m)
        d2 = _defect(M2, k, m)
        if i1 is None or i2 is None or f1 is None or f2 is None or d1 is None or d2 is None:
            return None
        differ = False
        for i in range(m):
            for j in range(m):
                if d1[i][j] != d2[i][j]:
                    differ = True
        return bool(_eqm(i1, i2) and _eqm(f1, f2) and differ)
    return None


def check_case(case):
    if not isinstance(case, dict):
        return False
    exp = case.get('expected')
    if not isinstance(exp, bool):
        return False
    pred = _predict(case)
    if pred is None or not isinstance(pred, bool):
        return False
    return bool(pred == exp)

from fractions import Fraction
from math import gcd, isqrt


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _to_frac_matrix(rows):
    if not isinstance(rows, list) or len(rows) == 0:
        return None
    out = []
    for row in rows:
        if not isinstance(row, list):
            return None
        new_row = []
        for x in row:
            if _is_int(x):
                new_row.append(Fraction(x))
            elif isinstance(x, Fraction):
                new_row.append(x)
            else:
                return None
        out.append(new_row)
    return out


def _is_square(mat):
    n = len(mat)
    for row in mat:
        if len(row) != n:
            return False
    return True


def _det(mat):
    n = len(mat)
    m = [row[:] for row in mat]
    det = Fraction(1)
    for col in range(n):
        pivot = -1
        for r in range(col, n):
            if m[r][col] != 0:
                pivot = r
                break
        if pivot < 0:
            return Fraction(0)
        if pivot != col:
            m[col], m[pivot] = m[pivot], m[col]
            det = -det
        det = det * m[col][col]
        inv = Fraction(1) / m[col][col]
        for r in range(col + 1, n):
            if m[r][col] != 0:
                factor = m[r][col] * inv
                for c in range(col, n):
                    m[r][c] = m[r][c] - factor * m[col][c]
    return det


def _matmul(X, Y):
    n = len(X)
    q = len(Y)
    p = len(Y[0])
    out = []
    for i in range(n):
        row = []
        for j in range(p):
            s = Fraction(0)
            for k in range(q):
                s = s + X[i][k] * Y[k][j]
            row.append(s)
        out.append(row)
    return out


def _transpose(X):
    return [list(col) for col in zip(*X)]


def _inverse(mat):
    n = len(mat)
    aug = []
    for i in range(n):
        row = mat[i][:]
        for j in range(n):
            if i == j:
                row.append(Fraction(1))
            else:
                row.append(Fraction(0))
        aug.append(row)
    for col in range(n):
        pivot = -1
        for r in range(col, n):
            if aug[r][col] != 0:
                pivot = r
                break
        if pivot < 0:
            return None
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]
        inv = Fraction(1) / aug[col][col]
        for c in range(2 * n):
            aug[col][c] = aug[col][c] * inv
        for r in range(n):
            if r != col and aug[r][col] != 0:
                factor = aug[r][col]
                for c in range(2 * n):
                    aug[r][c] = aug[r][c] - factor * aug[col][c]
    return [row[n:] for row in aug]


def _adjugate(mat):
    n = len(mat)
    if n == 1:
        return [[Fraction(1)]]
    cof = []
    for i in range(n):
        row = []
        for j in range(n):
            minor = []
            for r in range(n):
                if r == i:
                    continue
                mrow = []
                for c in range(n):
                    if c != j:
                        mrow.append(mat[r][c])
                minor.append(mrow)
            cof_ij = _det(minor)
            if (i + j) % 2 == 1:
                cof_ij = -cof_ij
            row.append(cof_ij)
        cof.append(row)
    return _transpose(cof)


def _schur(A, B, D):
    invA = _inverse(A)
    if invA is None:
        return None, None
    X = _matmul(invA, B)
    BtX = _matmul(_transpose(B), X)
    S = []
    for i in range(len(D)):
        row = []
        for j in range(len(D[0])):
            row.append(D[i][j] - BtX[i][j])
        S.append(row)
    return X, S


def _pred_schur_q(A, B, D):
    return _det(A) != 0


def _pred_schur_z(A, B, D):
    X, S = _schur(A, B, D)
    if X is None:
        return False
    for row in X:
        for x in row:
            if x.denominator != 1:
                return False
    return True


def _pred_scaled_z(A, B, D):
    d = _det(A)
    if d == 0:
        return False
    k = len(A)
    m = len(D)
    n = k + m
    adjB = _matmul(_adjugate(A), B)
    Bt = _transpose(B)
    M = [A[i] + B[i] for i in range(k)] + [Bt[i] + D[i] for i in range(m)]
    P = []
    for i in range(n):
        P.append([Fraction(0)] * n)
    for i in range(k):
        P[i][i] = d
    for i in range(k):
        for j in range(m):
            P[i][k + j] = -adjB[i][j]
    for i in range(m):
        P[k + i][k + i] = d
    left = _matmul(_matmul(_transpose(P), M), P)
    d2 = d * d
    BtAdjB = _matmul(Bt, adjB)
    target = []
    for i in range(n):
        target.append([Fraction(0)] * n)
    for i in range(k):
        for j in range(k):
            target[i][j] = d2 * A[i][j]
    for i in range(m):
        for j in range(m):
            target[k + i][k + j] = d2 * D[i][j] - d * BtAdjB[i][j]
    return left == target


def _pred_block_drop(A, B, D):
    X, S = _schur(A, B, D)
    if X is None:
        return False
    BtX = _matmul(_transpose(B), X)
    for row in BtX:
        for x in row:
            if x != 0:
                return False
    return True


def _is_square_frac(x):
    if x == 0:
        return True
    if x < 0:
        return False
    num = x.numerator
    den = x.denominator
    return isqrt(num) * isqrt(num) == num and isqrt(den) * isqrt(den) == den


def _pred_block_q(A, B, D):
    if len(D) != 1 or len(D[0]) != 1:
        return False
    X, S = _schur(A, B, D)
    if X is None:
        return False
    dd = D[0][0]
    s = S[0][0]
    if dd == 0 and s == 0:
        return True
    if dd == 0 or s == 0:
        return False
    return _is_square_frac(dd * s)


def _gf2_inverse(mat):
    n = len(mat)
    aug = []
    for i in range(n):
        row = [mat[i][j] % 2 for j in range(n)]
        for j in range(n):
            if i == j:
                row.append(1)
            else:
                row.append(0)
        aug.append(row)
    for col in range(n):
        pivot = -1
        for r in range(col, n):
            if aug[r][col] % 2 == 1:
                pivot = r
                break
        if pivot < 0:
            return None
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]
        for r in range(n):
            if r != col and aug[r][col] % 2 == 1:
                for c in range(2 * n):
                    aug[r][c] = (aug[r][c] + aug[col][c]) % 2
    return [row[n:] for row in aug]


def _frac_mod2(x):
    if x.denominator % 2 == 0:
        return None
    return x.numerator % 2


def _pred_gf2_fold(A, B, D):
    d = _det(A)
    if d.denominator != 1:
        return False
    if d.numerator % 2 == 0:
        return False
    X, S = _schur(A, B, D)
    if X is None:
        return False
    A2 = [[a.numerator % 2 for a in row] for row in A]
    B2 = [[b.numerator % 2 for b in row] for row in B]
    D2 = [[c.numerator % 2 for c in row] for row in D]
    invA2 = _gf2_inverse(A2)
    if invA2 is None:
        return False
    schur2 = _matmul(_matmul(_transpose(B2), invA2), B2)
    for i in range(len(D2)):
        for j in range(len(D2[0])):
            schur2[i][j] = (D2[i][j] + schur2[i][j]) % 2
    for i in range(len(S)):
        for j in range(len(S[0])):
            v = _frac_mod2(S[i][j])
            if v is None:
                return False
            if v != schur2[i][j]:
                return False
    return True


def check_case(case):
    if not isinstance(case, dict):
        return False
    predicate = case.get('predicate')
    expected = case.get('expected')
    if not isinstance(expected, bool):
        return False
    if predicate == 'mirror_eulerian':
        p = case.get('p')
        q = case.get('q')
        if not _is_int(p) or not _is_int(q):
            return False
        if p <= 0 or q <= 0:
            return False
        predicted = gcd(p, q) == 1
        return predicted == expected
    A = _to_frac_matrix(case.get('A'))
    B = _to_frac_matrix(case.get('B'))
    D = _to_frac_matrix(case.get('D'))
    if A is None or B is None or D is None:
        return False
    if not _is_square(A) or not _is_square(D):
        return False
    k = len(A)
    m = len(D)
    if len(B) != k:
        return False
    for row in B:
        if len(row) != m:
            return False
    if predicate == 'schur_q':
        predicted = _pred_schur_q(A, B, D)
    elif predicate == 'schur_z':
        predicted = _pred_schur_z(A, B, D)
    elif predicate == 'scaled_z':
        predicted = _pred_scaled_z(A, B, D)
    elif predicate == 'block_drop':
        predicted = _pred_block_drop(A, B, D)
    elif predicate == 'block_q':
        predicted = _pred_block_q(A, B, D)
    elif predicate == 'gf2_fold':
        predicted = _pred_gf2_fold(A, B, D)
    else:
        return False
    if not isinstance(predicted, bool):
        return False
    return predicted == expected

from fractions import Fraction
from math import gcd, isqrt

def transpose(a):
    return [list(row) for row in zip(*a)]

def multiply(a, b):
    return [[sum(a[i][t] * b[t][j] for t in range(len(b))) for j in range(len(b[0]))] for i in range(len(a))]

def subtract(a, b):
    return [[a[i][j] - b[i][j] for j in range(len(a[0]))] for i in range(len(a))]

def scale(a, c):
    return [[c * x for x in row] for row in a]

def parity(a):
    return [[x % 2 for x in row] for row in a]

def fraction_matrix(a):
    return [[Fraction(x, 1) for x in row] for row in a]

def minor(a, r, c):
    return [[a[i][j] for j in range(len(a)) if j != c] for i in range(len(a)) if i != r]

def determinant(a):
    n = len(a)
    if n == 0:
        return 1
    if n == 1:
        return a[0][0]
    total = 0
    for j in range(n):
        sign = -1 if j % 2 else 1
        total += sign * a[0][j] * determinant(minor(a, 0, j))
    return total

def adjugate(a):
    n = len(a)
    return [[(-1 if (i + j) % 2 else 1) * determinant(minor(a, j, i)) for j in range(n)] for i in range(n)]

def block_diag(a, b):
    ca = len(a[0])
    cb = len(b[0])
    za = 0 * a[0][0]
    zb = 0 * b[0][0]
    top = [list(a[i]) + [za for j in range(cb)] for i in range(len(a))]
    bottom = [[zb for j in range(ca)] + list(b[i]) for i in range(len(b))]
    return top + bottom

def assemble(a, b, d):
    bt = transpose(b)
    return [list(a[i]) + list(b[i]) for i in range(len(a))] + [list(bt[i]) + list(d[i]) for i in range(len(d))]

def schur_data(a, b, dblock):
    det_a = determinant(a)
    if det_a == 0:
        return None
    h = multiply(adjugate(a), b)
    x = [[Fraction(h[i][j], det_a) for j in range(len(h[0]))] for i in range(len(h))]
    s = subtract(fraction_matrix(dblock), multiply(transpose(b), x))
    return det_a, h, x, s

def rational_and_scaled(a, b, dblock):
    data = schur_data(a, b, dblock)
    if data is None:
        return False
    det_a, h, x, s = data
    k = len(a)
    m = len(dblock)
    n = k + m
    full = assemble(a, b, dblock)
    p = [[Fraction(0, 1) for j in range(n)] for i in range(n)]
    for i in range(n):
        p[i][i] = Fraction(1, 1)
    for i in range(k):
        for j in range(m):
            p[i][k + j] = -x[i][j]
    rational_lhs = multiply(multiply(transpose(p), fraction_matrix(full)), p)
    rational_rhs = block_diag(fraction_matrix(a), s)
    rational_ok = rational_lhs == rational_rhs
    pint = [[0 for j in range(n)] for i in range(n)]
    for i in range(n):
        pint[i][i] = det_a
    for i in range(k):
        for j in range(m):
            pint[i][k + j] = -h[i][j]
    correction = multiply(transpose(b), h)
    snum = subtract(scale(dblock, det_a * det_a), scale(correction, det_a))
    scaled_lhs = multiply(multiply(transpose(pint), full), pint)
    scaled_rhs = block_diag(scale(a, det_a * det_a), snum)
    scaled_ok = scaled_lhs == scaled_rhs
    det_ok = Fraction(determinant(full), 1) == det_a * determinant(s)
    pivot_det_ok = determinant(pint) == det_a ** n
    return rational_ok and scaled_ok and det_ok and pivot_det_ok

def canonical_integral(a, b, dblock):
    data = schur_data(a, b, dblock)
    if data is None:
        return False
    det_a, h, x, s = data
    x_integral = all(q.denominator == 1 for row in x for q in row)
    s_integral = all(q.denominator == 1 for row in s for q in row)
    return x_integral and s_integral

def rational_square(q):
    if q <= 0:
        return False
    n = q.numerator
    d = q.denominator
    return isqrt(n) * isqrt(n) == n and isqrt(d) * isqrt(d) == d

def scalar_block_data(a, b, dblock):
    data = schur_data(a, b, dblock)
    if data is None or len(dblock) != 1 or len(dblock[0]) != 1:
        return None
    det_a, h, x, s = data
    correction = multiply(transpose(b), x)
    canonical = all(q == 0 for row in correction for q in row)
    delta = dblock[0][0]
    sigma = s[0][0]
    if delta == 0 or sigma == 0:
        abstract = delta == 0 and sigma == 0
    else:
        abstract = rational_square(Fraction(delta, 1) * sigma)
    return canonical, abstract

def residue2(q):
    if q.denominator % 2 == 0:
        return None
    return q.numerator % 2

def gf2_fold(a, b, dblock):
    data = schur_data(a, b, dblock)
    if data is None or data[0] % 2 == 0:
        return False
    det_a, h, x, s = data
    a2 = parity(a)
    g2 = parity(adjugate(a))
    k = len(a)
    identity = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    inverse_ok = parity(multiply(a2, g2)) == identity and parity(multiply(g2, a2)) == identity
    residues = [residue2(q) for row in s for q in row]
    if any(q is None for q in residues):
        return False
    s2 = [[residues[i * len(s[0]) + j] for j in range(len(s[0]))] for i in range(len(s))]
    b2 = parity(b)
    d2 = parity(dblock)
    correction2 = multiply(multiply(transpose(b2), g2), b2)
    rhs = parity([[d2[i][j] + correction2[i][j] for j in range(len(d2[0]))] for i in range(len(d2))])
    return inverse_ok and s2 == rhs

def positive_definite(a):
    for k in range(1, len(a) + 1):
        leading = [list(a[i][:k]) for i in range(k)]
        if determinant(leading) <= 0:
            return False
    return True

def parity_matches_loewner(m, n):
    if parity(m) != parity(n):
        return True
    return positive_definite(m) == positive_definite(n)

def check_case(case):
    expected = case.get("expected")
    if not isinstance(expected, bool):
        return False
    kind = case.get("kind")
    if kind == "schur_q_scaled":
        observed = rational_and_scaled(case["A"], case["B"], case["D"])
    elif kind == "schur_z":
        observed = canonical_integral(case["A"], case["B"], case["D"])
    elif kind == "block_separation":
        values = scalar_block_data(case["A"], case["B"], case["D"])
        observed = False if values is None else (not values[0]) and values[1]
    elif kind == "gf2_fold":
        observed = gf2_fold(case["A"], case["B"], case["D"])
    elif kind == "gf2_loewner":
        observed = parity_matches_loewner(case["M"], case["N"])
    elif kind == "mirror_separation":
        observed = gcd(case["p"], case["q"]) == 1 and gcd(case["u"], case["v"]) == 2
    else:
        return False
    return isinstance(observed, bool) and observed == expected

from fractions import Fraction
from math import gcd, isqrt

def _int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def _mat_int(M):
    if not isinstance(M, list) or len(M) == 0:
        return False
    w = None
    for row in M:
        if not isinstance(row, list) or len(row) == 0:
            return False
        if w is None:
            w = len(row)
        if len(row) != w:
            return False
        for x in row:
            if not _int(x):
                return False
    return True

def _T(M):
    return [[M[i][j] for i in range(len(M))] for j in range(len(M[0]))]

def _mul(A, B):
    n = len(A)
    k = len(A[0])
    m = len(B[0])
    C = [[Fraction(0) for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for t in range(k):
            if A[i][t] == 0:
                continue
            for j in range(m):
                C[i][j] += A[i][t] * B[t][j]
    return C

def _det(A):
    n = len(A)
    M = [[Fraction(A[i][j]) for j in range(n)] for i in range(n)]
    sign = 1
    for c in range(n):
        piv = None
        for r in range(c, n):
            if M[r][c] != 0:
                piv = r
                break
        if piv is None:
            return Fraction(0)
        if piv != c:
            M[c], M[piv] = M[piv], M[c]
            sign = -sign
        pc = M[c][c]
        for r in range(c + 1, n):
            if M[r][c] == 0:
                continue
            f = M[r][c] / pc
            for j in range(c, n):
                M[r][j] -= f * M[c][j]
    d = Fraction(sign)
    for i in range(n):
        d *= M[i][i]
    return d

def _inv(A):
    n = len(A)
    M = []
    for i in range(n):
        M.append([Fraction(A[i][j]) for j in range(n)] + [Fraction(1 if i == j else 0) for j in range(n)])
    for c in range(n):
        piv = None
        for r in range(c, n):
            if M[r][c] != 0:
                piv = r
                break
        if piv is None:
            return None
        if piv != c:
            M[c], M[piv] = M[piv], M[c]
        pc = M[c][c]
        for j in range(2 * n):
            M[c][j] /= pc
        for r in range(n):
            if r == c or M[r][c] == 0:
                continue
            f = M[r][c]
            for j in range(2 * n):
                M[r][j] -= f * M[c][j]
    return [[M[i][n + j] for j in range(n)] for i in range(n)]

def _square_q(q):
    if q < 0:
        return False
    num = q.numerator
    den = q.denominator
    a = isqrt(num)
    b = isqrt(den)
    return a * a == num and b * b == den

def _gf2_inv(A):
    n = len(A)
    M = []
    for i in range(n):
        M.append([(A[i][j] % 2) for j in range(n)] + [1 if i == j else 0 for j in range(n)])
    for c in range(n):
        piv = None
        for r in range(c, n):
            if M[r][c] == 1:
                piv = r
                break
        if piv is None:
            return None
        if piv != c:
            M[c], M[piv] = M[piv], M[c]
        for r in range(n):
            if r != c and M[r][c] == 1:
                for j in range(2 * n):
                    M[r][j] = (M[r][j] + M[c][j]) % 2
    return [[M[i][n + j] for j in range(n)] for i in range(n)]

def _gf2_mul(A, B):
    n = len(A)
    k = len(A[0])
    m = len(B[0])
    C = [[0 for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for t in range(k):
            if A[i][t] % 2 == 0:
                continue
            for j in range(m):
                C[i][j] = (C[i][j] + B[t][j]) % 2
    return C

def check_case(case):
    if not isinstance(case, dict):
        return False
    kind = case.get("kind")
    expected = case.get("expected")
    if not isinstance(expected, bool):
        return False
    if kind == "mirror":
        p = case.get("p")
        q = case.get("q")
        if not _int(p) or not _int(q) or p <= 0 or q <= 0:
            return False
        return (gcd(p, q) == 1) == expected
    A = case.get("A")
    B = case.get("B")
    D = case.get("D")
    if not (_mat_int(A) and _mat_int(B) and _mat_int(D)):
        return False
    k = len(A)
    m = len(D)
    if len(A[0]) != k or len(B) != k or len(B[0]) != m or len(D[0]) != m:
        return False
    Af = [[Fraction(A[i][j]) for j in range(k)] for i in range(k)]
    Bf = [[Fraction(B[i][j]) for j in range(m)] for i in range(k)]
    Df = [[Fraction(D[i][j]) for j in range(m)] for i in range(m)]
    d = _det(Af)
    if d == 0:
        return (False == expected)
    Ainv = _inv(Af)
    if Ainv is None:
        return False
    X = _mul(Ainv, Bf)
    corr = _mul(_T(Bf), X)
    S = [[Df[i][j] - corr[i][j] for j in range(m)] for i in range(m)]
    if kind == "schur_z":
        pred = True
        for i in range(k):
            for j in range(m):
                if X[i][j].denominator != 1:
                    pred = False
        return pred == expected
    if kind == "block_canon":
        pred = True
        for i in range(m):
            for j in range(m):
                if corr[i][j] != 0:
                    pred = False
        return pred == expected
    if kind == "block_q":
        if m != 1:
            return False
        ds = Df[0][0]
        ss = S[0][0]
        if ds == 0 and ss == 0:
            pred = True
        elif ds == 0 or ss == 0:
            pred = False
        else:
            pred = _square_q(ds / ss)
        return pred == expected
    if kind == "gf2":
        if d.denominator != 1 or (d.numerator % 2) == 0:
            return (False == expected)
        A2 = [[A[i][j] % 2 for j in range(k)] for i in range(k)]
        B2 = [[B[i][j] % 2 for j in range(m)] for i in range(k)]
        D2 = [[D[i][j] % 2 for j in range(m)] for i in range(m)]
        A2i = _gf2_inv(A2)
        if A2i is None:
            return (False == expected)
        C2 = _gf2_mul(_T(B2), _gf2_mul(A2i, B2))
        pred = True
        for i in range(m):
            for j in range(m):
                if S[i][j].denominator % 2 == 0:
                    pred = False
                elif (S[i][j].numerator % 2) != ((D2[i][j] + C2[i][j]) % 2):
                    pred = False
        return pred == expected
    if kind == "scaled":
        n = k + m
        Mf = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        for i in range(k):
            for j in range(k):
                Mf[i][j] = Af[i][j]
        for i in range(k):
            for j in range(m):
                Mf[i][k + j] = Bf[i][j]
                Mf[k + j][i] = Bf[i][j]
        for i in range(m):
            for j in range(m):
                Mf[k + i][k + j] = Df[i][j]
        P = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        for i in range(k):
            P[i][i] = d
            for j in range(m):
                P[i][k + j] = -d * X[i][j]
        for i in range(m):
            P[k + i][k + i] = d
        PM = _mul(_T(P), _mul(Mf, P))
        pred = True
        for i in range(n):
            for j in range(n):
                val = PM[i][j]
                if val.denominator != 1:
                    pred = False
                if i < k and j < k:
                    if val != d * d * Af[i][j]:
                        pred = False
                elif i >= k and j >= k:
                    if val != d * d * S[i - k][j - k]:
                        pred = False
                elif val != 0:
                    pred = False
        return pred == expected
    return False
